-- >>>>>>>>>>>>>>>>>>>>  001_foundation.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 001_foundation.sql
-- Schemas, enums, shared helper functions, document numbering.
-- =============================================================================

create schema if not exists app;

comment on schema app is
  'Internal helpers. Not exposed through the API. Only the public schema is.';

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------

create type app.user_role as enum ('REP', 'ACCOUNTS', 'ADMIN');

create type app.uom_type as enum ('BASE', 'PACK');

create type app.stock_doc_type as enum (
  'OPENING',
  'PURCHASE',
  'PURCHASE_CANCEL',
  'SALE',
  'SALE_CANCEL',
  'SALE_RETURN',
  'SALE_RETURN_CANCEL',
  'ADJUSTMENT'
);

create type app.order_status as enum (
  'DRAFT',
  'SUBMITTED',
  'PARTIALLY_INVOICED',
  'INVOICED',
  'CANCELLED',
  'EXPIRED'
);

create type app.invoice_status as enum (
  'ACTIVE',
  'PARTIALLY_CANCELLED',
  'CANCELLED'
);

create type app.doc_status as enum ('ACTIVE', 'CANCELLED');

create type app.payment_mode as enum ('CASH', 'BANK', 'CHEQUE', 'DIGITAL');

create type app.adjustment_reason as enum (
  'DAMAGE',
  'SAMPLE',
  'COUNT_CORRECTION',
  'EXPIRY',
  'OTHER'
);

create type app.doc_series as enum (
  'PURCHASE',
  'SALES_ORDER',
  'SALES_INVOICE',
  'SALES_RETURN',
  'STOCK_ADJUSTMENT',
  'RECEIPT',
  'INVOICE_CANCELLATION'
);

-- -----------------------------------------------------------------------------
-- Shared: updated_at maintenance
-- -----------------------------------------------------------------------------

create or replace function app.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Shared: block UPDATE and DELETE on append-only tables
-- -----------------------------------------------------------------------------

create or replace function app.forbid_change()
returns trigger
language plpgsql
as $$
begin
  raise exception
    '% is append-only; % is not permitted', tg_table_name, tg_op
    using errcode = 'restrict_violation';
end;
$$;

-- -----------------------------------------------------------------------------
-- Document numbering
--
-- Format: <prefix><zero-padded number>, e.g. INV-000123.
-- Numbering format is configurable per series so it can be finalised later
-- without a schema change.
-- -----------------------------------------------------------------------------

create table app.doc_sequence (
  series        app.doc_series primary key,
  prefix        text        not null default '',
  next_number   bigint      not null default 1 check (next_number > 0),
  pad_width     smallint    not null default 6 check (pad_width between 1 and 12),
  updated_at    timestamptz not null default now()
);

insert into app.doc_sequence (series, prefix) values
  ('PURCHASE',             'PUR-'),
  ('SALES_ORDER',          'SO-'),
  ('SALES_INVOICE',        'INV-'),
  ('SALES_RETURN',         'SR-'),
  ('STOCK_ADJUSTMENT',     'ADJ-'),
  ('RECEIPT',              'RCT-'),
  ('INVOICE_CANCELLATION', 'CAN-');

-- Belt and braces. This table is already unreachable from a client: it lives
-- in the app schema, which PostgREST does not expose, and 012_rls.sql revokes
-- everything on that schema from anon and authenticated. RLS with no policy
-- denies by default, so this closes the door a third time. next_doc_no is
-- SECURITY DEFINER owned by this table's owner, which RLS does not restrain,
-- so numbering is unaffected.
alter table app.doc_sequence enable row level security;

-- Locks the sequence row for the duration of the caller's transaction, so two
-- concurrent documents can never take the same number.
create or replace function app.next_doc_no(p_series app.doc_series)
returns text
language plpgsql
security definer
set search_path = app, pg_catalog
as $$
declare
  v_prefix text;
  v_number bigint;
  v_width  smallint;
begin
  update app.doc_sequence
     set next_number = next_number + 1,
         updated_at  = now()
   where series = p_series
  returning prefix, next_number - 1, pad_width
    into v_prefix, v_number, v_width;

  if not found then
    raise exception 'Unknown document series: %', p_series;
  end if;

  return v_prefix || lpad(v_number::text, v_width, '0');
end;
$$;

-- -----------------------------------------------------------------------------
-- Money helpers
-- -----------------------------------------------------------------------------

-- Rounds half away from zero at 2 decimals. Postgres numeric rounding is
-- already half-up for positive values; this exists so every call site is
-- explicit and consistent.
create or replace function app.money(p numeric)
returns numeric
language sql
immutable
as $$ select round(coalesce(p, 0), 2); $$;

-- >>>>>>>>>>>>>>>>>>>>  002_users.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 002_users.sql
-- Application users. One row per auth.users row, carrying the role.
-- =============================================================================

create table public.app_user (
  id          uuid primary key references auth.users (id) on delete restrict,
  full_name   text           not null check (length(btrim(full_name)) > 0),
  role        app.user_role  not null default 'REP',
  phone       text,
  is_active   boolean        not null default true,
  created_at  timestamptz    not null default now(),
  updated_at  timestamptz    not null default now()
);

comment on table public.app_user is
  'Profile and role for each login. Deactivate rather than delete: users are
   referenced by every document they created.';

create trigger app_user_touch
  before update on public.app_user
  for each row execute function app.touch_updated_at();

create index app_user_role_idx on public.app_user (role) where is_active;

-- -----------------------------------------------------------------------------
-- Role helpers used by every RLS policy.
--
-- SECURITY DEFINER so that reading app_user does not itself require a policy
-- that reads app_user (which would recurse). STABLE so the planner calls them
-- once per statement rather than once per row.
-- -----------------------------------------------------------------------------

create or replace function app.current_role()
returns app.user_role
language sql
stable
security definer
set search_path = public, pg_catalog
as $$
  select u.role
    from public.app_user u
   where u.id = auth.uid()
     and u.is_active;
$$;

create or replace function app.is_admin()
returns boolean
language sql
stable
as $$ select app.current_role() = 'ADMIN'; $$;

-- Accounts and Admin both post financial documents.
create or replace function app.is_back_office()
returns boolean
language sql
stable
as $$ select app.current_role() in ('ACCOUNTS', 'ADMIN'); $$;

create or replace function app.is_signed_in()
returns boolean
language sql
stable
as $$ select app.current_role() is not null; $$;

-- >>>>>>>>>>>>>>>>>>>>  003_masters.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 003_masters.sql
-- Route, product group, supplier, party, product.
--
-- Masters are never hard-deleted once transactions reference them; they are
-- deactivated with is_active = false.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Route
-- -----------------------------------------------------------------------------

create table public.route (
  id          uuid primary key default gen_random_uuid(),
  code        text        not null unique check (length(btrim(code)) > 0),
  name        text        not null check (length(btrim(name)) > 0),
  is_active   boolean     not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create trigger route_touch before update on public.route
  for each row execute function app.touch_updated_at();

-- -----------------------------------------------------------------------------
-- Product group
-- -----------------------------------------------------------------------------

create table public.product_group (
  id          uuid primary key default gen_random_uuid(),
  code        text        not null unique check (length(btrim(code)) > 0),
  name        text        not null check (length(btrim(name)) > 0),
  is_active   boolean     not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create trigger product_group_touch before update on public.product_group
  for each row execute function app.touch_updated_at();

-- -----------------------------------------------------------------------------
-- Supplier
-- -----------------------------------------------------------------------------

create table public.supplier (
  id             uuid primary key default gen_random_uuid(),
  code           text        not null unique check (length(btrim(code)) > 0),
  name           text        not null check (length(btrim(name)) > 0),
  contact_person text,
  phone          text,
  address        text,
  city           text,
  is_active      boolean     not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create trigger supplier_touch before update on public.supplier
  for each row execute function app.touch_updated_at();

create index supplier_name_idx on public.supplier using gin (to_tsvector('simple', name));

-- -----------------------------------------------------------------------------
-- Party (customer)
-- -----------------------------------------------------------------------------

create table public.party (
  id                   uuid primary key default gen_random_uuid(),
  code                 text        not null unique check (length(btrim(code)) > 0),
  name                 text        not null check (length(btrim(name)) > 0),
  route_id             uuid        not null references public.route (id) on delete restrict,
  contact_person       text,
  phone                text,
  whatsapp_phone       text,
  address              text,
  city                 text,

  -- 0 means "no limit". Enforcement behaviour is a setting, see app_setting.
  credit_limit         numeric(14,2) not null default 0 check (credit_limit >= 0),
  credit_days          smallint      not null default 0 check (credit_days >= 0),

  -- Receivable carried in at go-live. Positive = customer owes us.
  opening_balance      numeric(14,2) not null default 0,
  opening_balance_date date,

  is_active            boolean     not null default true,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),

  constraint party_opening_needs_date
    check (opening_balance = 0 or opening_balance_date is not null)
);

comment on column public.party.opening_balance is
  'Amount receivable as at opening_balance_date. Set once at go-live by Admin.';

create trigger party_touch before update on public.party
  for each row execute function app.touch_updated_at();

create index party_route_idx on public.party (route_id) where is_active;
create index party_name_idx  on public.party using gin (to_tsvector('simple', name));

-- -----------------------------------------------------------------------------
-- Product
--
-- Stock is always held in the BASE unit. pack_size is how many base units are
-- in one pack; it is snapshotted onto every document line so that changing it
-- later never rewrites history.
-- -----------------------------------------------------------------------------

create table public.product (
  id             uuid primary key default gen_random_uuid(),
  code           text        not null unique check (length(btrim(code)) > 0),
  name           text        not null check (length(btrim(name)) > 0),
  group_id       uuid        not null references public.product_group (id) on delete restrict,

  base_uom       text        not null check (length(btrim(base_uom)) > 0),
  pack_uom       text,
  pack_size      numeric(14,4) not null default 1 check (pack_size > 0),

  -- Both rates are per BASE unit.
  sale_rate      numeric(14,4) not null default 0 check (sale_rate >= 0),
  purchase_rate  numeric(14,4) not null default 0 check (purchase_rate >= 0),

  opening_qty    numeric(14,4) not null default 0 check (opening_qty >= 0),
  opening_rate   numeric(14,4) not null default 0 check (opening_rate >= 0),
  opening_date   date,

  is_active      boolean     not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  -- A pack unit only means something if it differs from the base unit.
  constraint product_pack_consistent
    check (
      (pack_uom is null and pack_size = 1)
      or (pack_uom is not null and length(btrim(pack_uom)) > 0)
    ),

  constraint product_opening_needs_date
    check (opening_qty = 0 or opening_date is not null)
);

comment on column public.product.pack_size is
  'Base units per pack. 1 box of 24 pieces => base_uom PCS, pack_uom BOX, pack_size 24.';

create trigger product_touch before update on public.product
  for each row execute function app.touch_updated_at();

create index product_group_idx on public.product (group_id) where is_active;
create index product_name_idx  on public.product using gin (to_tsvector('simple', name));

-- -----------------------------------------------------------------------------
-- Application settings
--
-- Single-row table. Business rules that may change without a code deploy.
-- -----------------------------------------------------------------------------

create table public.app_setting (
  id                        boolean primary key default true check (id),
  business_name             text          not null default 'My Business',
  business_address          text,
  business_phone            text,

  -- Sales orders with no invoice are released after this many days.
  reservation_expiry_days   smallint      not null default 2
                              check (reservation_expiry_days between 1 and 30),

  -- 'IGNORE' | 'WARN' | 'BLOCK'
  credit_limit_mode         text          not null default 'WARN'
                              check (credit_limit_mode in ('IGNORE', 'WARN', 'BLOCK')),

  -- Reps may see how much each party owes.
  reps_see_outstanding      boolean       not null default true,

  -- Round the invoice net total to the nearest whole currency unit.
  round_invoice_total       boolean       not null default true,

  updated_at                timestamptz   not null default now()
);

insert into public.app_setting (id) values (true);

create trigger app_setting_touch before update on public.app_setting
  for each row execute function app.touch_updated_at();

create or replace function app.settings()
returns public.app_setting
language sql
stable
security definer
set search_path = public, pg_catalog
as $$ select * from public.app_setting where id; $$;

-- >>>>>>>>>>>>>>>>>>>>  004_stock.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 004_stock.sql
-- The stock ledger (append-only, source of truth) and the cached balance.
--
-- Every movement of goods writes exactly one ledger row. product_stock is a
-- derived cache maintained by trigger; a reconciliation view compares the two.
-- =============================================================================

create table public.stock_ledger (
  id            uuid primary key default gen_random_uuid(),
  product_id    uuid          not null references public.product (id) on delete restrict,
  movement_date date          not null,

  qty_in        numeric(14,4) not null default 0 check (qty_in  >= 0),
  qty_out       numeric(14,4) not null default 0 check (qty_out >= 0),
  rate          numeric(14,4) not null default 0 check (rate    >= 0),

  doc_type      app.stock_doc_type not null,
  doc_id        uuid,
  doc_line_id   uuid,
  notes         text,

  created_at    timestamptz   not null default now(),
  created_by    uuid          references public.app_user (id),

  -- Exactly one direction per row. Keeps the ledger unambiguous to read.
  constraint stock_ledger_one_direction
    check ((qty_in > 0 and qty_out = 0) or (qty_out > 0 and qty_in = 0))
);

comment on table public.stock_ledger is
  'Append-only. Never updated, never deleted. Corrections are new reversing rows.';

create trigger stock_ledger_no_update
  before update or delete on public.stock_ledger
  for each row execute function app.forbid_change();

create index stock_ledger_product_idx on public.stock_ledger (product_id, movement_date);
create index stock_ledger_doc_idx     on public.stock_ledger (doc_type, doc_id);

-- -----------------------------------------------------------------------------
-- Cached balance
--
-- on_hand >= 0 is a hard CHECK. This is the last line of defence behind the
-- application logic: even a bug cannot drive stock negative, the transaction
-- simply fails.
-- -----------------------------------------------------------------------------

create table public.product_stock (
  product_id  uuid primary key references public.product (id) on delete restrict,
  on_hand     numeric(14,4) not null default 0 check (on_hand  >= 0),
  reserved    numeric(14,4) not null default 0 check (reserved >= 0),
  available   numeric(14,4) generated always as (on_hand - reserved) stored,
  updated_at  timestamptz   not null default now()
);

comment on column public.product_stock.reserved is
  'Committed to submitted sales orders not yet invoiced. Not a stock movement,
   so it is maintained by the order functions rather than by the ledger.';

create index product_stock_available_idx on public.product_stock (available);

-- Every product gets a stock row the moment it is created.
create or replace function app.create_stock_row()
returns trigger
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
begin
  insert into public.product_stock (product_id) values (new.id)
  on conflict (product_id) do nothing;
  return new;
end;
$$;

create trigger product_create_stock_row
  after insert on public.product
  for each row execute function app.create_stock_row();

-- Ledger row in, cached balance updated. The only writer of on_hand.
--
-- Deliberately UPDATE-then-INSERT rather than INSERT ... ON CONFLICT DO UPDATE.
-- An upsert evaluates CHECK constraints against the proposed insert row before
-- it detects the conflict, so a stock-out of 24 would be checked as -24 >= 0
-- and rejected before the update path was ever reached. Every product gets its
-- stock row when it is created, so the UPDATE is the normal path; the INSERT is
-- a fallback that should never fire.
create or replace function app.apply_ledger_to_stock()
returns trigger
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
begin
  update public.product_stock
     set on_hand    = on_hand + (new.qty_in - new.qty_out),
         updated_at = now()
   where product_id = new.product_id;

  if not found then
    insert into public.product_stock (product_id, on_hand)
    values (new.product_id, new.qty_in - new.qty_out);
  end if;

  return new;
end;
$$;

create trigger stock_ledger_apply
  after insert on public.stock_ledger
  for each row execute function app.apply_ledger_to_stock();

-- -----------------------------------------------------------------------------
-- Reconciliation: the cache must always agree with the ledger.
-- Run this as a scheduled check; any row returned is a bug worth investigating.
-- -----------------------------------------------------------------------------

create or replace view public.v_stock_reconciliation as
select
  p.id                                   as product_id,
  p.code,
  p.name,
  coalesce(ps.on_hand, 0)                as cached_on_hand,
  coalesce(sum(sl.qty_in - sl.qty_out), 0) as ledger_on_hand,
  coalesce(ps.on_hand, 0) - coalesce(sum(sl.qty_in - sl.qty_out), 0) as difference
from public.product p
left join public.product_stock ps on ps.product_id = p.id
left join public.stock_ledger  sl on sl.product_id = p.id
group by p.id, p.code, p.name, ps.on_hand
having coalesce(ps.on_hand, 0) <> coalesce(sum(sl.qty_in - sl.qty_out), 0);

comment on view public.v_stock_reconciliation is
  'Should always be empty. Any row means the cached balance drifted from the ledger.';

-- -----------------------------------------------------------------------------
-- Opening stock
--
-- Posts each product''s opening_qty as an OPENING ledger row. Idempotent:
-- a product that already has an OPENING row is skipped.
-- -----------------------------------------------------------------------------

create or replace function public.post_opening_stock()
returns integer
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_count integer := 0;
begin
  if not app.is_admin() then
    raise exception 'Only Admin may post opening stock'
      using errcode = 'insufficient_privilege';
  end if;

  insert into public.stock_ledger
    (product_id, movement_date, qty_in, rate, doc_type, notes, created_by)
  select p.id, p.opening_date, p.opening_qty, p.opening_rate, 'OPENING',
         'Opening stock at go-live', auth.uid()
    from public.product p
   where p.opening_qty > 0
     and p.opening_date is not null
     and not exists (
           select 1 from public.stock_ledger sl
            where sl.product_id = p.id and sl.doc_type = 'OPENING'
         );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>  005_purchase.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 005_purchase.sql
-- Purchase entry. The only routine way stock increases.
--
-- A posted purchase is never edited. Correction is cancellation plus re-entry,
-- exactly as with a sales invoice.
-- =============================================================================

create table public.purchase (
  id                 uuid primary key default gen_random_uuid(),
  doc_no             text        not null unique,
  supplier_id        uuid        not null references public.supplier (id) on delete restrict,
  purchase_date      date        not null,
  supplier_bill_no   text,
  supplier_bill_date date,

  gross_total        numeric(14,2) not null default 0 check (gross_total   >= 0),
  other_charges      numeric(14,2) not null default 0 check (other_charges >= 0),
  net_total          numeric(14,2) not null default 0 check (net_total     >= 0),

  status             app.doc_status not null default 'ACTIVE',
  remarks            text,

  created_at         timestamptz not null default now(),
  created_by         uuid        references public.app_user (id),
  cancelled_at       timestamptz,
  cancelled_by       uuid        references public.app_user (id),
  cancel_reason      text,

  constraint purchase_cancel_fields
    check (
      (status = 'ACTIVE'    and cancelled_at is null and cancel_reason is null)
      or
      (status = 'CANCELLED' and cancelled_at is not null
                            and length(btrim(coalesce(cancel_reason, ''))) > 0)
    )
);

create index purchase_supplier_idx on public.purchase (supplier_id, purchase_date desc);
create index purchase_date_idx     on public.purchase (purchase_date desc);

create table public.purchase_line (
  id          uuid primary key default gen_random_uuid(),
  purchase_id uuid          not null references public.purchase (id) on delete cascade,
  line_no     smallint      not null check (line_no > 0),
  product_id  uuid          not null references public.product (id) on delete restrict,

  uom         app.uom_type  not null default 'BASE',
  qty         numeric(14,4) not null check (qty > 0),
  pack_size   numeric(14,4) not null default 1 check (pack_size > 0),
  rate        numeric(14,4) not null check (rate >= 0),

  -- Quantity in base units. Stock only ever moves in base units.
  qty_base    numeric(14,4)
    generated always as (qty * case when uom = 'PACK' then pack_size else 1 end) stored,

  amount      numeric(14,2)
    generated always as (round(qty * rate, 2)) stored,

  unique (purchase_id, line_no),

  -- A PACK line is meaningless when the product has no pack.
  constraint purchase_line_pack_sane
    check (uom = 'BASE' or pack_size > 1)
);

create index purchase_line_purchase_idx on public.purchase_line (purchase_id);
create index purchase_line_product_idx  on public.purchase_line (product_id);

-- -----------------------------------------------------------------------------
-- Header totals must equal the sum of the lines. Checked at COMMIT so that a
-- multi-statement insert (header, then lines) is legal in between.
-- -----------------------------------------------------------------------------

-- The check itself, addressed by purchase id.
create or replace function app.check_purchase_totals(p_purchase_id uuid)
returns void
language plpgsql
as $$
declare
  v_head     public.purchase%rowtype;
  v_line_sum numeric(14,2);
begin
  select * into v_head from public.purchase where id = p_purchase_id;
  if not found then
    return;  -- header removed in the same transaction; nothing to verify
  end if;

  select coalesce(sum(amount), 0) into v_line_sum
    from public.purchase_line where purchase_id = p_purchase_id;

  if v_head.gross_total <> v_line_sum then
    raise exception
      'Purchase % gross_total is % but its lines sum to %',
      v_head.doc_no, v_head.gross_total, v_line_sum
      using errcode = 'check_violation';
  end if;

  if v_head.net_total <> v_head.gross_total + v_head.other_charges then
    raise exception
      'Purchase % net_total % does not equal gross % plus charges %',
      v_head.doc_no, v_head.net_total, v_head.gross_total, v_head.other_charges
      using errcode = 'check_violation';
  end if;
end;
$$;

-- Two thin wrappers rather than one shared function: plpgsql resolves NEW and
-- OLD field references against the triggering table, so a single function
-- referencing both purchase.id and purchase_line.purchase_id fails on whichever
-- table lacks the column. NEW is also unassigned on DELETE.
create or replace function app.tg_check_purchase_totals_head()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    return null;
  end if;
  perform app.check_purchase_totals(new.id);
  return null;
end;
$$;

create or replace function app.tg_check_purchase_totals_line()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    perform app.check_purchase_totals(old.purchase_id);
  else
    perform app.check_purchase_totals(new.purchase_id);
  end if;
  return null;
end;
$$;

create constraint trigger purchase_totals_check
  after insert or update on public.purchase
  deferrable initially deferred
  for each row execute function app.tg_check_purchase_totals_head();

create constraint trigger purchase_line_totals_check
  after insert or update or delete on public.purchase_line
  deferrable initially deferred
  for each row execute function app.tg_check_purchase_totals_line();

-- >>>>>>>>>>>>>>>>>>>>  006_sales_order.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 006_sales_order.sql
-- Sales orders collected by reps. Submitting an order reserves stock.
--
-- Lifecycle:
--   DRAFT -> SUBMITTED -> PARTIALLY_INVOICED -> INVOICED
--                      -> CANCELLED
--                      -> EXPIRED  (auto-released after N days)
-- =============================================================================

create table public.sales_order (
  id            uuid primary key default gen_random_uuid(),
  doc_no        text        not null unique,
  party_id      uuid        not null references public.party (id) on delete restrict,
  order_date    date        not null,
  status        app.order_status not null default 'DRAFT',
  remarks       text,

  submitted_at  timestamptz,
  -- When the reservation lapses if nothing has been invoiced.
  expires_at    timestamptz,

  closed_at     timestamptz,
  cancelled_at  timestamptz,
  cancelled_by  uuid        references public.app_user (id),
  cancel_reason text,

  created_at    timestamptz not null default now(),
  created_by    uuid        references public.app_user (id),
  updated_at    timestamptz not null default now(),

  constraint sales_order_submitted_fields
    check (status = 'DRAFT' or submitted_at is not null),

  constraint sales_order_cancel_fields
    check (
      status <> 'CANCELLED'
      or (cancelled_at is not null
          and length(btrim(coalesce(cancel_reason, ''))) > 0)
    )
);

comment on column public.sales_order.expires_at is
  'Set on submit from app_setting.reservation_expiry_days. The release job
   compares against this, so changing the setting does not retroactively
   expire orders already in flight.';

create trigger sales_order_touch before update on public.sales_order
  for each row execute function app.touch_updated_at();

create index sales_order_party_idx  on public.sales_order (party_id, order_date desc);
create index sales_order_status_idx on public.sales_order (status);
create index sales_order_rep_idx    on public.sales_order (created_by, order_date desc);

-- Orders still holding a reservation, for the expiry job.
create index sales_order_expiry_idx on public.sales_order (expires_at)
  where status in ('SUBMITTED', 'PARTIALLY_INVOICED');

-- -----------------------------------------------------------------------------
-- Order lines
--
-- qty_invoiced_base and qty_cancelled_base are maintained by the invoice and
-- cancel functions. Whatever remains is what is still reserved.
-- -----------------------------------------------------------------------------

create table public.sales_order_line (
  id                 uuid primary key default gen_random_uuid(),
  order_id           uuid          not null references public.sales_order (id) on delete cascade,
  line_no            smallint      not null check (line_no > 0),
  product_id         uuid          not null references public.product (id) on delete restrict,

  uom                app.uom_type  not null default 'BASE',
  qty                numeric(14,4) not null check (qty > 0),
  pack_size          numeric(14,4) not null default 1 check (pack_size > 0),
  rate               numeric(14,4) not null check (rate >= 0),

  qty_base           numeric(14,4)
    generated always as (qty * case when uom = 'PACK' then pack_size else 1 end) stored,

  qty_invoiced_base  numeric(14,4) not null default 0 check (qty_invoiced_base  >= 0),
  qty_cancelled_base numeric(14,4) not null default 0 check (qty_cancelled_base >= 0),

  -- Still reserved, assuming the order is in a reserving status.
  qty_pending_base   numeric(14,4)
    generated always as (
      qty * case when uom = 'PACK' then pack_size else 1 end
      - qty_invoiced_base - qty_cancelled_base
    ) stored,

  unique (order_id, line_no),
  -- One row per product per order keeps reservation arithmetic unambiguous.
  unique (order_id, product_id),

  constraint sales_order_line_not_over_consumed
    check (
      qty_invoiced_base + qty_cancelled_base
      <= qty * case when uom = 'PACK' then pack_size else 1 end
    ),

  constraint sales_order_line_pack_sane
    check (uom = 'BASE' or pack_size > 1)
);

create index sales_order_line_order_idx   on public.sales_order_line (order_id);
create index sales_order_line_product_idx on public.sales_order_line (product_id);

-- -----------------------------------------------------------------------------
-- What the order is currently worth, and what it still holds in reserve.
-- -----------------------------------------------------------------------------

create or replace view public.v_sales_order_summary as
select
  so.id                        as order_id,
  so.doc_no,
  so.party_id,
  so.order_date,
  so.status,
  so.expires_at,
  so.created_by                as rep_id,
  count(sol.id)                as line_count,
  coalesce(sum(round(sol.qty * sol.rate, 2)), 0) as order_value,
  coalesce(sum(sol.qty_pending_base), 0)         as qty_pending_base,
  case
    when so.status in ('SUBMITTED', 'PARTIALLY_INVOICED')
    then coalesce(sum(sol.qty_pending_base), 0)
    else 0
  end                          as qty_reserved_base
from public.sales_order so
left join public.sales_order_line sol on sol.order_id = so.id
group by so.id;

-- >>>>>>>>>>>>>>>>>>>>  007_sales_invoice.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 007_sales_invoice.sql
-- Sales invoices and their cancellations.
--
-- An invoice, once posted, is IMMUTABLE. Its lines and amounts are never
-- rewritten. A correction is a separate invoice_cancellation document whose
-- value is subtracted from the invoice, so the original always remains legible.
-- =============================================================================

create table public.sales_invoice (
  id                   uuid primary key default gen_random_uuid(),
  doc_no               text        not null unique,
  party_id             uuid        not null references public.party (id) on delete restrict,

  -- Normally raised from an order. NULL means a direct counter sale, which
  -- reserves nothing and consumes stock immediately.
  order_id             uuid        references public.sales_order (id) on delete restrict,

  invoice_date         date        not null,

  gross_total          numeric(14,2) not null default 0 check (gross_total         >= 0),
  line_discount_total  numeric(14,2) not null default 0 check (line_discount_total >= 0),
  bill_discount_amount numeric(14,2) not null default 0 check (bill_discount_amount >= 0),
  round_off            numeric(14,2) not null default 0,
  net_total            numeric(14,2) not null default 0 check (net_total >= 0),

  -- Raised by cancellations. Never exceeds net_total.
  cancelled_value      numeric(14,2) not null default 0 check (cancelled_value >= 0),

  -- What the customer actually owes for this invoice before payments.
  effective_total      numeric(14,2)
    generated always as (net_total - cancelled_value) stored,

  status               app.invoice_status not null default 'ACTIVE',
  remarks              text,

  created_at           timestamptz not null default now(),
  created_by           uuid        references public.app_user (id),

  constraint sales_invoice_cancel_not_over
    check (cancelled_value <= net_total),

  constraint sales_invoice_status_consistent
    check (
      (status = 'ACTIVE'              and cancelled_value = 0)
      or (status = 'PARTIALLY_CANCELLED' and cancelled_value > 0 and cancelled_value < net_total)
      or (status = 'CANCELLED'            and cancelled_value = net_total)
    )
);

comment on column public.sales_invoice.cancelled_value is
  'Sum of all cancellation documents against this invoice. Maintained by trigger.';

create index sales_invoice_party_idx  on public.sales_invoice (party_id, invoice_date desc);
create index sales_invoice_date_idx   on public.sales_invoice (invoice_date desc);
create index sales_invoice_order_idx  on public.sales_invoice (order_id);
create index sales_invoice_status_idx on public.sales_invoice (status);

-- -----------------------------------------------------------------------------
-- Invoice lines. Immutable once written.
--
-- allocated_bill_discount is the invoice-level discount pushed down to this
-- line in proportion to its net value, so that product-wise margin reporting
-- is correct. effective_amount is what all such reporting uses.
-- -----------------------------------------------------------------------------

create table public.sales_invoice_line (
  id                      uuid primary key default gen_random_uuid(),
  invoice_id              uuid          not null references public.sales_invoice (id) on delete cascade,
  line_no                 smallint      not null check (line_no > 0),
  order_line_id           uuid          references public.sales_order_line (id) on delete restrict,
  product_id              uuid          not null references public.product (id) on delete restrict,

  uom                     app.uom_type  not null default 'BASE',
  qty                     numeric(14,4) not null check (qty > 0),
  pack_size               numeric(14,4) not null default 1 check (pack_size > 0),
  rate                    numeric(14,4) not null check (rate >= 0),

  qty_base                numeric(14,4)
    generated always as (qty * case when uom = 'PACK' then pack_size else 1 end) stored,

  -- Stored as a resolved amount. The percentage, if one was typed, is kept
  -- alongside purely so the invoice can be reprinted showing "10%".
  line_discount_pct       numeric(7,4)  check (line_discount_pct between 0 and 100),
  line_discount_amount    numeric(14,2) not null default 0 check (line_discount_amount >= 0),

  allocated_bill_discount numeric(14,2) not null default 0 check (allocated_bill_discount >= 0),

  gross_amount numeric(14,2)
    generated always as (round(qty * rate, 2)) stored,

  net_amount numeric(14,2)
    generated always as (round(qty * rate, 2) - line_discount_amount) stored,

  effective_amount numeric(14,2)
    generated always as (
      round(qty * rate, 2) - line_discount_amount - allocated_bill_discount
    ) stored,

  -- Base quantity cancelled by cancellation documents. Maintained by trigger.
  qty_cancelled_base      numeric(14,4) not null default 0 check (qty_cancelled_base >= 0),

  unique (invoice_id, line_no),

  constraint sales_invoice_line_discount_not_over
    check (line_discount_amount + allocated_bill_discount <= round(qty * rate, 2)),

  constraint sales_invoice_line_cancel_not_over
    check (
      qty_cancelled_base
      <= qty * case when uom = 'PACK' then pack_size else 1 end
    ),

  constraint sales_invoice_line_pack_sane
    check (uom = 'BASE' or pack_size > 1)
);

create index sales_invoice_line_invoice_idx on public.sales_invoice_line (invoice_id);
create index sales_invoice_line_product_idx on public.sales_invoice_line (product_id);
create index sales_invoice_line_order_idx   on public.sales_invoice_line (order_line_id);

-- -----------------------------------------------------------------------------
-- Header totals must equal the sum of the lines, at COMMIT.
--
-- This is what guarantees the bill-discount allocation adds up exactly. If the
-- largest-remainder allocation ever drifts by a paisa, the transaction fails
-- rather than quietly writing an invoice whose lines do not sum to its total.
-- -----------------------------------------------------------------------------

create or replace function app.check_invoice_totals(p_invoice_id uuid)
returns void
language plpgsql
as $$
declare
  v_head      public.sales_invoice%rowtype;
  v_gross     numeric(14,2);
  v_line_disc numeric(14,2);
  v_bill_disc numeric(14,2);
  v_effective numeric(14,2);
begin
  select * into v_head from public.sales_invoice where id = p_invoice_id;
  if not found then
    return;
  end if;

  select coalesce(sum(gross_amount), 0),
         coalesce(sum(line_discount_amount), 0),
         coalesce(sum(allocated_bill_discount), 0),
         coalesce(sum(effective_amount), 0)
    into v_gross, v_line_disc, v_bill_disc, v_effective
    from public.sales_invoice_line
   where invoice_id = p_invoice_id;

  if v_head.gross_total <> v_gross then
    raise exception 'Invoice % gross_total % <> line sum %',
      v_head.doc_no, v_head.gross_total, v_gross using errcode = 'check_violation';
  end if;

  if v_head.line_discount_total <> v_line_disc then
    raise exception 'Invoice % line_discount_total % <> line sum %',
      v_head.doc_no, v_head.line_discount_total, v_line_disc using errcode = 'check_violation';
  end if;

  -- The allocation must consume the bill discount exactly, to the paisa.
  if v_head.bill_discount_amount <> v_bill_disc then
    raise exception
      'Invoice %: bill discount % was allocated to lines as % — allocation must be exact',
      v_head.doc_no, v_head.bill_discount_amount, v_bill_disc
      using errcode = 'check_violation';
  end if;

  if v_head.net_total <> v_effective + v_head.round_off then
    raise exception 'Invoice % net_total % <> effective line sum % plus round off %',
      v_head.doc_no, v_head.net_total, v_effective, v_head.round_off
      using errcode = 'check_violation';
  end if;
end;
$$;

create or replace function app.tg_check_invoice_totals_head()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    return null;
  end if;
  perform app.check_invoice_totals(new.id);
  return null;
end;
$$;

create or replace function app.tg_check_invoice_totals_line()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    perform app.check_invoice_totals(old.invoice_id);
  else
    perform app.check_invoice_totals(new.invoice_id);
  end if;
  return null;
end;
$$;

create constraint trigger sales_invoice_totals_check
  after insert or update on public.sales_invoice
  deferrable initially deferred
  for each row execute function app.tg_check_invoice_totals_head();

create constraint trigger sales_invoice_line_totals_check
  after insert or update or delete on public.sales_invoice_line
  deferrable initially deferred
  for each row execute function app.tg_check_invoice_totals_line();

-- =============================================================================
-- Invoice cancellation documents
-- =============================================================================

create table public.invoice_cancellation (
  id                uuid primary key default gen_random_uuid(),
  doc_no            text        not null unique,
  invoice_id        uuid        not null references public.sales_invoice (id) on delete restrict,
  cancellation_date date        not null,

  -- true when every remaining line and quantity was cancelled at once.
  is_full           boolean     not null default false,

  cancelled_value   numeric(14,2) not null check (cancelled_value > 0),
  reason            text        not null check (length(btrim(reason)) > 0),

  created_at        timestamptz not null default now(),
  created_by        uuid        references public.app_user (id)
);

comment on table public.invoice_cancellation is
  'Reverses part or all of an invoice. The invoice itself is never modified,
   so the original document can always be reprinted as issued.';

create index invoice_cancellation_invoice_idx
  on public.invoice_cancellation (invoice_id);

create table public.invoice_cancellation_line (
  id               uuid primary key default gen_random_uuid(),
  cancellation_id  uuid          not null references public.invoice_cancellation (id) on delete cascade,
  invoice_line_id  uuid          not null references public.sales_invoice_line (id) on delete restrict,
  product_id       uuid          not null references public.product (id) on delete restrict,

  qty_base         numeric(14,4) not null check (qty_base > 0),

  -- The invoice line's effective value, pro-rated to the cancelled quantity.
  cancelled_value  numeric(14,2) not null check (cancelled_value >= 0),

  unique (cancellation_id, invoice_line_id)
);

create index invoice_cancellation_line_cancel_idx
  on public.invoice_cancellation_line (cancellation_id);
create index invoice_cancellation_line_invline_idx
  on public.invoice_cancellation_line (invoice_line_id);

-- >>>>>>>>>>>>>>>>>>>>  008_sales_return.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 008_sales_return.sql
-- Goods physically returned by a customer after delivery.
--
-- Distinct from an invoice cancellation: a cancellation says the sale never
-- properly happened, a return says goods came back. A return puts stock back
-- and creates a credit that can be allocated against outstanding invoices.
-- =============================================================================

create table public.sales_return (
  id            uuid primary key default gen_random_uuid(),
  doc_no        text        not null unique,
  party_id      uuid        not null references public.party (id) on delete restrict,

  -- Optional: a return can reference the invoice it came from, which pre-fills
  -- products and rates, or stand alone when the original cannot be traced.
  invoice_id    uuid        references public.sales_invoice (id) on delete restrict,

  return_date   date        not null,
  total_value   numeric(14,2) not null default 0 check (total_value >= 0),

  status        app.doc_status not null default 'ACTIVE',
  reason        text        not null check (length(btrim(reason)) > 0),
  remarks       text,

  created_at    timestamptz not null default now(),
  created_by    uuid        references public.app_user (id),
  cancelled_at  timestamptz,
  cancelled_by  uuid        references public.app_user (id),
  cancel_reason text,

  constraint sales_return_cancel_fields
    check (
      (status = 'ACTIVE'    and cancelled_at is null)
      or
      (status = 'CANCELLED' and cancelled_at is not null
                            and length(btrim(coalesce(cancel_reason, ''))) > 0)
    )
);

create index sales_return_party_idx   on public.sales_return (party_id, return_date desc);
create index sales_return_invoice_idx on public.sales_return (invoice_id);
create index sales_return_date_idx    on public.sales_return (return_date desc);

create table public.sales_return_line (
  id              uuid primary key default gen_random_uuid(),
  return_id       uuid          not null references public.sales_return (id) on delete cascade,
  line_no         smallint      not null check (line_no > 0),
  product_id      uuid          not null references public.product (id) on delete restrict,
  invoice_line_id uuid          references public.sales_invoice_line (id) on delete restrict,

  uom             app.uom_type  not null default 'BASE',
  qty             numeric(14,4) not null check (qty > 0),
  pack_size       numeric(14,4) not null default 1 check (pack_size > 0),
  rate            numeric(14,4) not null check (rate >= 0),

  qty_base        numeric(14,4)
    generated always as (qty * case when uom = 'PACK' then pack_size else 1 end) stored,

  amount          numeric(14,2)
    generated always as (round(qty * rate, 2)) stored,

  -- Returned goods are not always resaleable. Damaged returns credit the
  -- customer but do not go back into sellable stock.
  restock         boolean       not null default true,

  unique (return_id, line_no),

  constraint sales_return_line_pack_sane
    check (uom = 'BASE' or pack_size > 1)
);

comment on column public.sales_return_line.restock is
  'false means the customer is credited but the goods are written off rather
   than added back to on_hand.';

create index sales_return_line_return_idx  on public.sales_return_line (return_id);
create index sales_return_line_product_idx on public.sales_return_line (product_id);

-- -----------------------------------------------------------------------------
-- Header total must equal the sum of the lines, at COMMIT.
-- -----------------------------------------------------------------------------

create or replace function app.check_return_totals(p_return_id uuid)
returns void
language plpgsql
as $$
declare
  v_head     public.sales_return%rowtype;
  v_line_sum numeric(14,2);
begin
  select * into v_head from public.sales_return where id = p_return_id;
  if not found then
    return;
  end if;

  select coalesce(sum(amount), 0) into v_line_sum
    from public.sales_return_line where return_id = p_return_id;

  if v_head.total_value <> v_line_sum then
    raise exception 'Sales return % total_value % <> line sum %',
      v_head.doc_no, v_head.total_value, v_line_sum
      using errcode = 'check_violation';
  end if;
end;
$$;

create or replace function app.tg_check_return_totals_head()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    return null;
  end if;
  perform app.check_return_totals(new.id);
  return null;
end;
$$;

create or replace function app.tg_check_return_totals_line()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    perform app.check_return_totals(old.return_id);
  else
    perform app.check_return_totals(new.return_id);
  end if;
  return null;
end;
$$;

create constraint trigger sales_return_totals_check
  after insert or update on public.sales_return
  deferrable initially deferred
  for each row execute function app.tg_check_return_totals_head();

create constraint trigger sales_return_line_totals_check
  after insert or update or delete on public.sales_return_line
  deferrable initially deferred
  for each row execute function app.tg_check_return_totals_line();

-- >>>>>>>>>>>>>>>>>>>>  009_stock_adjustment.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 009_stock_adjustment.sql
-- Manual stock corrections: damage, samples, physical count differences.
--
-- Every adjustment requires a reason. These are the rows an owner looks at
-- first when stock does not match the shelf, so they are always audited and
-- never anonymous.
-- =============================================================================

create table public.stock_adjustment (
  id              uuid primary key default gen_random_uuid(),
  doc_no          text        not null unique,
  adjustment_date date        not null,
  reason          app.adjustment_reason not null,
  notes           text,

  status          app.doc_status not null default 'ACTIVE',

  created_at      timestamptz not null default now(),
  created_by      uuid        references public.app_user (id),
  cancelled_at    timestamptz,
  cancelled_by    uuid        references public.app_user (id),
  cancel_reason   text,

  -- OTHER is free-form, so it must be explained.
  constraint stock_adjustment_other_needs_notes
    check (reason <> 'OTHER' or length(btrim(coalesce(notes, ''))) > 0),

  constraint stock_adjustment_cancel_fields
    check (
      (status = 'ACTIVE'    and cancelled_at is null)
      or
      (status = 'CANCELLED' and cancelled_at is not null
                            and length(btrim(coalesce(cancel_reason, ''))) > 0)
    )
);

create index stock_adjustment_date_idx on public.stock_adjustment (adjustment_date desc);

create table public.stock_adjustment_line (
  id             uuid primary key default gen_random_uuid(),
  adjustment_id  uuid          not null references public.stock_adjustment (id) on delete cascade,
  line_no        smallint      not null check (line_no > 0),
  product_id     uuid          not null references public.product (id) on delete restrict,

  direction      text          not null check (direction in ('IN', 'OUT')),
  uom            app.uom_type  not null default 'BASE',
  qty            numeric(14,4) not null check (qty > 0),
  pack_size      numeric(14,4) not null default 1 check (pack_size > 0),
  rate           numeric(14,4) not null default 0 check (rate >= 0),

  qty_base       numeric(14,4)
    generated always as (qty * case when uom = 'PACK' then pack_size else 1 end) stored,

  unique (adjustment_id, line_no),

  constraint stock_adjustment_line_pack_sane
    check (uom = 'BASE' or pack_size > 1)
);

create index stock_adjustment_line_adj_idx     on public.stock_adjustment_line (adjustment_id);
create index stock_adjustment_line_product_idx on public.stock_adjustment_line (product_id);

-- >>>>>>>>>>>>>>>>>>>>  010_receipt.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 010_receipt.sql
-- Payment receipts and the allocation of credits against invoices.
--
-- A credit is either money received or the value of returned goods. Both are
-- allocated to invoices through one table, so ageing works identically for
-- each and an invoice is settled the same way regardless of how.
-- =============================================================================

create table public.receipt (
  id               uuid primary key default gen_random_uuid(),
  doc_no           text        not null unique,
  party_id         uuid        not null references public.party (id) on delete restrict,
  receipt_date     date        not null,

  mode             app.payment_mode not null,
  amount           numeric(14,2) not null check (amount > 0),

  reference_no     text,
  instrument_date  date,
  bank_name        text,

  -- Only meaningful for CHEQUE. NULL for every other mode.
  clearing_status  text check (clearing_status in ('PENDING', 'CLEARED', 'BOUNCED')),

  -- Who physically took the money. For a rep collecting cash in the field this
  -- is the rep, while created_by is the Accounts user who entered it.
  collected_by     uuid        references public.app_user (id),

  status           app.doc_status not null default 'ACTIVE',
  remarks          text,

  created_at       timestamptz not null default now(),
  created_by       uuid        references public.app_user (id),
  cancelled_at     timestamptz,
  cancelled_by     uuid        references public.app_user (id),
  cancel_reason    text,

  constraint receipt_cheque_fields
    check (
      (mode = 'CHEQUE' and clearing_status is not null)
      or
      (mode <> 'CHEQUE' and clearing_status is null)
    ),

  constraint receipt_cancel_fields
    check (
      (status = 'ACTIVE'    and cancelled_at is null)
      or
      (status = 'CANCELLED' and cancelled_at is not null
                            and length(btrim(coalesce(cancel_reason, ''))) > 0)
    )
);

comment on column public.receipt.clearing_status is
  'Cheques only. A BOUNCED cheque keeps its receipt but its allocations are
   reversed, putting the invoices back into outstanding.';

create index receipt_party_idx     on public.receipt (party_id, receipt_date desc);
create index receipt_date_idx      on public.receipt (receipt_date desc);
create index receipt_collector_idx on public.receipt (collected_by, receipt_date desc);
create index receipt_pending_cheque_idx on public.receipt (instrument_date)
  where mode = 'CHEQUE' and clearing_status = 'PENDING';

-- -----------------------------------------------------------------------------
-- Credit allocation
--
-- Exactly one source per row: a receipt or a sales return, never both.
-- -----------------------------------------------------------------------------

create table public.credit_allocation (
  id              uuid primary key default gen_random_uuid(),
  receipt_id      uuid references public.receipt (id)      on delete cascade,
  sales_return_id uuid references public.sales_return (id) on delete cascade,
  invoice_id      uuid not null references public.sales_invoice (id) on delete restrict,

  amount          numeric(14,2) not null check (amount > 0),

  created_at      timestamptz not null default now(),
  created_by      uuid        references public.app_user (id),

  constraint credit_allocation_one_source
    check (num_nonnulls(receipt_id, sales_return_id) = 1)
);

-- One line per source-and-invoice pair; change the amount rather than adding
-- a second row, so the allocation screen always shows one figure per invoice.
create unique index credit_allocation_receipt_invoice_idx
  on public.credit_allocation (receipt_id, invoice_id)
  where receipt_id is not null;

create unique index credit_allocation_return_invoice_idx
  on public.credit_allocation (sales_return_id, invoice_id)
  where sales_return_id is not null;

create index credit_allocation_invoice_idx on public.credit_allocation (invoice_id);

-- -----------------------------------------------------------------------------
-- Allocations may never exceed either side: not the credit that funds them,
-- nor the invoice they settle. Checked at COMMIT.
-- -----------------------------------------------------------------------------

create or replace function app.check_allocation_limits(
  p_receipt_id uuid,
  p_return_id  uuid,
  p_invoice_id uuid
)
returns void
language plpgsql
as $$
declare
  v_receipt_id uuid := p_receipt_id;
  v_return_id  uuid := p_return_id;
  v_invoice_id uuid := p_invoice_id;
  v_allocated  numeric(14,2);
  v_limit      numeric(14,2);
  v_doc_no     text;
begin
  if v_receipt_id is not null then
    select r.amount, r.doc_no into v_limit, v_doc_no
      from public.receipt r where r.id = v_receipt_id;

    if found then
      select coalesce(sum(amount), 0) into v_allocated
        from public.credit_allocation where receipt_id = v_receipt_id;

      if v_allocated > v_limit then
        raise exception
          'Receipt %: allocated % exceeds the receipt amount %',
          v_doc_no, v_allocated, v_limit using errcode = 'check_violation';
      end if;
    end if;
  end if;

  if v_return_id is not null then
    select sr.total_value, sr.doc_no into v_limit, v_doc_no
      from public.sales_return sr where sr.id = v_return_id;

    if found then
      select coalesce(sum(amount), 0) into v_allocated
        from public.credit_allocation where sales_return_id = v_return_id;

      if v_allocated > v_limit then
        raise exception
          'Sales return %: allocated % exceeds the return value %',
          v_doc_no, v_allocated, v_limit using errcode = 'check_violation';
      end if;
    end if;
  end if;

  select si.effective_total, si.doc_no into v_limit, v_doc_no
    from public.sales_invoice si where si.id = v_invoice_id;

  if found then
    select coalesce(sum(amount), 0) into v_allocated
      from public.credit_allocation where invoice_id = v_invoice_id;

    if v_allocated > v_limit then
      raise exception
        'Invoice %: allocated % exceeds what the invoice is worth (%)',
        v_doc_no, v_allocated, v_limit using errcode = 'check_violation';
    end if;
  end if;
end;
$$;

-- NEW is unassigned on DELETE and OLD on INSERT, so each case is read
-- separately rather than coalesced.
create or replace function app.tg_check_allocation_limits()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then
    perform app.check_allocation_limits(
      old.receipt_id, old.sales_return_id, old.invoice_id);
  else
    perform app.check_allocation_limits(
      new.receipt_id, new.sales_return_id, new.invoice_id);

    -- An UPDATE that moves an allocation to a different invoice or source
    -- leaves the old one needing a re-check too.
    if tg_op = 'UPDATE' then
      if old.invoice_id is distinct from new.invoice_id
         or old.receipt_id is distinct from new.receipt_id
         or old.sales_return_id is distinct from new.sales_return_id then
        perform app.check_allocation_limits(
          old.receipt_id, old.sales_return_id, old.invoice_id);
      end if;
    end if;
  end if;
  return null;
end;
$$;

create constraint trigger credit_allocation_limits_check
  after insert or update or delete on public.credit_allocation
  deferrable initially deferred
  for each row execute function app.tg_check_allocation_limits();

-- A cancellation that reduces an invoice below what is allocated to it would
-- break the rule above. The cancel function moves the excess to on-account
-- first, so this trigger exists to catch the case where that is ever missed.
create or replace function app.check_invoice_allocation_after_cancel()
returns trigger
language plpgsql
as $$
declare
  v_allocated numeric(14,2);
begin
  select coalesce(sum(amount), 0) into v_allocated
    from public.credit_allocation where invoice_id = new.id;

  if v_allocated > new.effective_total then
    raise exception
      'Invoice % is now worth % but has % allocated to it; release the excess to on-account first',
      new.doc_no, new.effective_total, v_allocated
      using errcode = 'check_violation';
  end if;

  return null;
end;
$$;

create constraint trigger sales_invoice_allocation_check
  after update of cancelled_value on public.sales_invoice
  deferrable initially deferred
  for each row execute function app.check_invoice_allocation_after_cancel();

-- >>>>>>>>>>>>>>>>>>>>  011_audit.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 011_audit.sql
-- Append-only audit log covering every master and transactional table.
--
-- Nobody, including Admin, can update or delete a row here. Admin can read it.
-- =============================================================================

create table public.audit_log (
  id          bigserial primary key,
  table_name  text        not null,
  row_id      text        not null,
  action      text        not null check (action in ('INSERT', 'UPDATE', 'DELETE')),
  old_values  jsonb,
  new_values  jsonb,
  -- Only the fields that actually changed, for a readable history view.
  changed     jsonb,
  changed_by  uuid,
  changed_at  timestamptz not null default now()
);

create trigger audit_log_no_change
  before update or delete on public.audit_log
  for each row execute function app.forbid_change();

create index audit_log_row_idx  on public.audit_log (table_name, row_id, changed_at desc);
create index audit_log_user_idx on public.audit_log (changed_by, changed_at desc);
create index audit_log_time_idx on public.audit_log (changed_at desc);

-- -----------------------------------------------------------------------------
-- Generic audit trigger.
-- -----------------------------------------------------------------------------

create or replace function app.audit_row()
returns trigger
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_old     jsonb;
  v_new     jsonb;
  v_changed jsonb;
  v_row_id  text;
  v_actor   uuid;
begin
  -- auth.uid() is absent when a migration or a cron job is the actor.
  begin
    v_actor := auth.uid();
  exception when others then
    v_actor := null;
  end;

  if tg_op = 'DELETE' then
    v_old    := to_jsonb(old);
    v_row_id := v_old ->> 'id';
  elsif tg_op = 'INSERT' then
    v_new    := to_jsonb(new);
    v_row_id := v_new ->> 'id';
  else
    v_old    := to_jsonb(old);
    v_new    := to_jsonb(new);
    v_row_id := v_new ->> 'id';

    select jsonb_object_agg(key, value) into v_changed
      from jsonb_each(v_new)
     where key not in ('updated_at')
       and (v_old -> key) is distinct from value;

    -- Nothing of substance changed; do not write a noise row.
    if v_changed is null then
      return null;
    end if;
  end if;

  insert into public.audit_log
    (table_name, row_id, action, old_values, new_values, changed, changed_by)
  values
    (tg_table_name, coalesce(v_row_id, '?'), tg_op, v_old, v_new, v_changed, v_actor);

  return null;
end;
$$;

-- -----------------------------------------------------------------------------
-- Attach to every table worth auditing.
-- -----------------------------------------------------------------------------

do $$
declare
  t text;
  audited text[] := array[
    'app_user', 'app_setting',
    'route', 'product_group', 'supplier', 'party', 'product',
    'purchase', 'purchase_line',
    'sales_order', 'sales_order_line',
    'sales_invoice', 'sales_invoice_line',
    'invoice_cancellation', 'invoice_cancellation_line',
    'sales_return', 'sales_return_line',
    'stock_adjustment', 'stock_adjustment_line',
    'receipt', 'credit_allocation'
  ];
begin
  foreach t in array audited loop
    execute format(
      'create trigger %I after insert or update or delete on public.%I
         for each row execute function app.audit_row()',
      t || '_audit', t
    );
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Readable per-document history, for the "who changed what" panel.
-- -----------------------------------------------------------------------------

create or replace view public.v_document_history as
select
  al.id,
  al.table_name,
  al.row_id,
  al.action,
  al.changed,
  al.changed_at,
  al.changed_by,
  u.full_name as changed_by_name,
  u.role      as changed_by_role
from public.audit_log al
left join public.app_user u on u.id = al.changed_by;

-- >>>>>>>>>>>>>>>>>>>>  012_rls.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 012_rls.sql
-- Row-level security.
--
-- Posture: clients may READ what their role allows and WRITE almost nothing
-- directly. Every document is created through a SECURITY DEFINER function in
-- 013, which performs its own permission check. A compromised or buggy client
-- therefore cannot post a document, move stock, or settle an invoice by
-- talking to the tables.
--
-- The only direct writes permitted are master data by Admin, where there is
-- no stock or money arithmetic to get wrong.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Start from nothing. Supabase grants broadly by default; we grant back
-- deliberately, table by table.
-- -----------------------------------------------------------------------------

revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke all on all functions in schema public from anon, authenticated;
revoke all on schema app                    from anon, authenticated;

-- Signed-out users get nothing at all.
grant usage on schema public to authenticated;

do $$
declare t text;
begin
  foreach t in array array[
    'app_user', 'app_setting',
    'route', 'product_group', 'supplier', 'party', 'product',
    'product_stock', 'stock_ledger',
    'purchase', 'purchase_line',
    'sales_order', 'sales_order_line',
    'sales_invoice', 'sales_invoice_line',
    'invoice_cancellation', 'invoice_cancellation_line',
    'sales_return', 'sales_return_line',
    'stock_adjustment', 'stock_adjustment_line',
    'receipt', 'credit_allocation',
    'audit_log'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Reference data every signed-in user needs
-- -----------------------------------------------------------------------------

grant select on
  public.app_user, public.app_setting,
  public.route, public.product_group, public.party, public.product,
  public.product_stock
to authenticated;

create policy app_user_read on public.app_user
  for select to authenticated using (app.is_signed_in());

create policy app_setting_read on public.app_setting
  for select to authenticated using (app.is_signed_in());

create policy route_read on public.route
  for select to authenticated using (app.is_signed_in());

create policy product_group_read on public.product_group
  for select to authenticated using (app.is_signed_in());

create policy party_read on public.party
  for select to authenticated using (app.is_signed_in());

create policy product_read on public.product
  for select to authenticated using (app.is_signed_in());

-- Reps need live availability; this is the whole point of the rep app.
create policy product_stock_read on public.product_stock
  for select to authenticated using (app.is_signed_in());

-- -----------------------------------------------------------------------------
-- Master maintenance — Admin only, direct writes allowed
-- -----------------------------------------------------------------------------

grant insert, update on
  public.route, public.product_group, public.supplier,
  public.party, public.product
to authenticated;

grant update on public.app_setting to authenticated;
grant insert, update on public.app_user to authenticated;

do $$
declare t text;
begin
  foreach t in array array[
    'route', 'product_group', 'supplier', 'party', 'product', 'app_user'
  ] loop
    execute format(
      'create policy %I on public.%I for insert to authenticated
         with check (app.is_admin())', t || '_admin_insert', t);
    execute format(
      'create policy %I on public.%I for update to authenticated
         using (app.is_admin()) with check (app.is_admin())',
      t || '_admin_update', t);
  end loop;
end;
$$;

create policy app_setting_admin_update on public.app_setting
  for update to authenticated
  using (app.is_admin()) with check (app.is_admin());

-- Deliberately no DELETE policy anywhere. Masters are deactivated, not deleted.

-- -----------------------------------------------------------------------------
-- Back-office-only reading
-- -----------------------------------------------------------------------------

grant select on
  public.supplier, public.stock_ledger,
  public.purchase, public.purchase_line,
  public.invoice_cancellation, public.invoice_cancellation_line,
  public.sales_return, public.sales_return_line,
  public.stock_adjustment, public.stock_adjustment_line
to authenticated;

do $$
declare t text;
begin
  foreach t in array array[
    'supplier', 'stock_ledger',
    'purchase', 'purchase_line',
    'invoice_cancellation', 'invoice_cancellation_line',
    'sales_return', 'sales_return_line',
    'stock_adjustment', 'stock_adjustment_line'
  ] loop
    execute format(
      'create policy %I on public.%I for select to authenticated
         using (app.is_back_office())', t || '_read', t);
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Orders — visible to everyone signed in
--
-- All routes are open to all reps, so orders are not partitioned by rep. When
-- that changes, this is the single place it changes.
-- -----------------------------------------------------------------------------

grant select on public.sales_order, public.sales_order_line to authenticated;

create policy sales_order_read on public.sales_order
  for select to authenticated using (app.is_signed_in());

create policy sales_order_line_read on public.sales_order_line
  for select to authenticated using (app.is_signed_in());

-- -----------------------------------------------------------------------------
-- Money — invoices, receipts, allocations
--
-- Back office always. Reps only while app_setting.reps_see_outstanding is on,
-- because seeing invoices is seeing who owes what.
-- -----------------------------------------------------------------------------

create or replace function app.can_see_money()
returns boolean
language sql
stable
as $$
  select app.is_back_office()
      or (app.current_role() = 'REP' and (app.settings()).reps_see_outstanding);
$$;

grant select on
  public.sales_invoice, public.sales_invoice_line,
  public.receipt, public.credit_allocation
to authenticated;

create policy sales_invoice_read on public.sales_invoice
  for select to authenticated using (app.can_see_money());

create policy sales_invoice_line_read on public.sales_invoice_line
  for select to authenticated using (app.can_see_money());

create policy receipt_read on public.receipt
  for select to authenticated using (app.can_see_money());

create policy credit_allocation_read on public.credit_allocation
  for select to authenticated using (app.can_see_money());

-- -----------------------------------------------------------------------------
-- Audit log — Admin reads, nobody writes
-- -----------------------------------------------------------------------------

grant select on public.audit_log to authenticated;

create policy audit_log_read on public.audit_log
  for select to authenticated using (app.is_admin());

-- -----------------------------------------------------------------------------
-- Helper functions used by policies must be callable by clients.
-- -----------------------------------------------------------------------------

grant usage on schema app to authenticated;

grant execute on function
  app.current_role(), app.is_admin(), app.is_back_office(),
  app.is_signed_in(), app.can_see_money(), app.settings()
to authenticated;

-- -----------------------------------------------------------------------------
-- Views inherit the policies of their underlying tables only when created with
-- security_invoker. Without it a view silently becomes a hole in RLS.
-- -----------------------------------------------------------------------------

alter view public.v_stock_reconciliation set (security_invoker = true);
alter view public.v_sales_order_summary  set (security_invoker = true);
alter view public.v_document_history     set (security_invoker = true);

grant select on
  public.v_stock_reconciliation,
  public.v_sales_order_summary,
  public.v_document_history
to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  013_functions.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 013_functions.sql
-- Business logic. Every operation that moves stock or money lives here.
--
-- All of these are SECURITY DEFINER: they bypass RLS and do their own
-- permission check, so the tables themselves can stay read-only to clients.
-- Each runs in a single transaction and locks the product stock rows it
-- touches, in product_id order, before reading availability.
--
-- Error codes returned to the client:
--   SA001  insufficient stock  (DETAIL carries a JSON array of shortfalls)
--   SA002  invalid state for the requested operation
--   SA003  permission denied
--   SA004  invalid input
--   SA005  not found
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Guards
-- -----------------------------------------------------------------------------

create or replace function app.require_signed_in()
returns uuid
language plpgsql
stable
as $$
declare v_id uuid := auth.uid();
begin
  if v_id is null or app.current_role() is null then
    raise exception 'Not signed in' using errcode = 'SA003';
  end if;
  return v_id;
end;
$$;

create or replace function app.require_back_office()
returns uuid
language plpgsql
stable
as $$
declare v_id uuid := app.require_signed_in();
begin
  if not app.is_back_office() then
    raise exception 'This action is for Accounts or Admin only'
      using errcode = 'SA003';
  end if;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Deterministic locking.
--
-- Two transactions touching the same two products in opposite orders would
-- deadlock. Sorting the ids first means every transaction takes its locks in
-- the same sequence, so one simply waits for the other.
-- -----------------------------------------------------------------------------

create or replace function app.lock_products(p_ids uuid[])
returns void
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_sorted uuid[];
  v_id     uuid;
begin
  select array_agg(distinct u order by u) into v_sorted from unnest(p_ids) u;

  foreach v_id in array coalesce(v_sorted, '{}'::uuid[]) loop
    perform 1 from public.product_stock where product_id = v_id for update;
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Resolve the pack size to snapshot for a line.
-- -----------------------------------------------------------------------------

create or replace function app.pack_size_for(p_product_id uuid, p_uom app.uom_type)
returns numeric
language plpgsql
stable
security definer
set search_path = public, pg_catalog
as $$
declare v_pack numeric;
begin
  select pack_size into v_pack from public.product where id = p_product_id;

  if not found then
    raise exception 'Unknown product %', p_product_id using errcode = 'SA005';
  end if;

  if p_uom = 'PACK' and v_pack <= 1 then
    raise exception 'Product % has no pack unit defined', p_product_id
      using errcode = 'SA004';
  end if;

  return case when p_uom = 'PACK' then v_pack else 1 end;
end;
$$;

-- =============================================================================
-- PURCHASE
-- =============================================================================

create or replace function public.post_purchase(
  p_supplier_id        uuid,
  p_purchase_date      date,
  p_lines              jsonb,
  p_other_charges      numeric default 0,
  p_supplier_bill_no   text    default null,
  p_supplier_bill_date date    default null,
  p_remarks            text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_back_office();
  v_doc_no text;
  v_id     uuid;
  v_gross  numeric(14,2);
begin
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'A purchase needs at least one line' using errcode = 'SA004';
  end if;

  drop table if exists _pur_lines;
  create temp table _pur_lines on commit drop as
  select
    row_number() over ()                        as line_no,
    x.product_id,
    x.uom,
    x.qty,
    app.pack_size_for(x.product_id, x.uom)      as pack_size,
    x.rate
  from jsonb_to_recordset(p_lines)
       as x(product_id uuid, uom app.uom_type, qty numeric, rate numeric);

  if exists (select 1 from pg_temp._pur_lines where qty is null or qty <= 0) then
    raise exception 'Every purchase line needs a quantity above zero'
      using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._pur_lines where rate is null or rate < 0) then
    raise exception 'Every purchase line needs a rate' using errcode = 'SA004';
  end if;

  select coalesce(sum(round(qty * rate, 2)), 0) into v_gross from pg_temp._pur_lines;

  v_doc_no := app.next_doc_no('PURCHASE');

  insert into public.purchase
    (doc_no, supplier_id, purchase_date, supplier_bill_no, supplier_bill_date,
     gross_total, other_charges, net_total, remarks, created_by)
  values
    (v_doc_no, p_supplier_id, p_purchase_date, p_supplier_bill_no,
     p_supplier_bill_date, v_gross, coalesce(p_other_charges, 0),
     v_gross + coalesce(p_other_charges, 0), p_remarks, v_user)
  returning id into v_id;

  insert into public.purchase_line
    (purchase_id, line_no, product_id, uom, qty, pack_size, rate)
  select v_id, line_no, product_id, uom, qty, pack_size, rate
    from pg_temp._pur_lines;

  -- Stock in.
  insert into public.stock_ledger
    (product_id, movement_date, qty_in, rate, doc_type, doc_id, doc_line_id, created_by)
  select pl.product_id, p_purchase_date, pl.qty_base,
         case when pl.qty_base > 0 then round(pl.amount / pl.qty_base, 4) else 0 end,
         'PURCHASE', v_id, pl.id, v_user
    from public.purchase_line pl
   where pl.purchase_id = v_id;

  return jsonb_build_object('purchase_id', v_id, 'doc_no', v_doc_no,
                            'net_total', v_gross + coalesce(p_other_charges, 0));
end;
$$;

-- =============================================================================
-- SALES ORDER
-- =============================================================================

-- Releases whatever an order still holds. Safe to call more than once.
create or replace function app.release_order_reservation(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare v_ids uuid[];
begin
  select array_agg(product_id) into v_ids
    from public.sales_order_line where order_id = p_order_id;

  perform app.lock_products(coalesce(v_ids, '{}'::uuid[]));

  update public.product_stock ps
     set reserved   = greatest(ps.reserved - sol.qty_pending_base, 0),
         updated_at = now()
    from public.sales_order_line sol
   where sol.order_id = p_order_id
     and ps.product_id = sol.product_id
     and sol.qty_pending_base > 0;
end;
$$;

-- Takes the reservation for an order's pending quantity, or raises SA001 with
-- a per-line breakdown of what is short.
create or replace function app.reserve_for_order(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_ids       uuid[];
  v_shortfall jsonb;
begin
  select array_agg(product_id) into v_ids
    from public.sales_order_line where order_id = p_order_id;

  perform app.lock_products(coalesce(v_ids, '{}'::uuid[]));

  select jsonb_agg(jsonb_build_object(
           'product_id',   sol.product_id,
           'product_code', p.code,
           'product_name', p.name,
           'base_uom',     p.base_uom,
           'requested',    sol.qty_pending_base,
           'available',    greatest(ps.available, 0)
         ) order by p.name)
    into v_shortfall
    from public.sales_order_line sol
    join public.product       p  on p.id  = sol.product_id
    join public.product_stock ps on ps.product_id = sol.product_id
   where sol.order_id = p_order_id
     and sol.qty_pending_base > ps.available;

  if v_shortfall is not null then
    raise exception 'Not enough stock for this order'
      using errcode = 'SA001', detail = v_shortfall::text;
  end if;

  update public.product_stock ps
     set reserved   = ps.reserved + sol.qty_pending_base,
         updated_at = now()
    from public.sales_order_line sol
   where sol.order_id = p_order_id
     and ps.product_id = sol.product_id
     and sol.qty_pending_base > 0;
end;
$$;

create or replace function public.create_sales_order(
  p_party_id   uuid,
  p_order_date date,
  p_lines      jsonb,
  p_remarks    text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_signed_in();
  v_doc_no text;
  v_id     uuid;
  v_days   smallint := (app.settings()).reservation_expiry_days;
begin
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'An order needs at least one line' using errcode = 'SA004';
  end if;

  if not exists (select 1 from public.party where id = p_party_id and is_active) then
    raise exception 'Unknown or inactive party' using errcode = 'SA005';
  end if;

  drop table if exists _ord_lines;
  create temp table _ord_lines on commit drop as
  select
    row_number() over ()                   as line_no,
    x.product_id,
    x.uom,
    x.qty,
    app.pack_size_for(x.product_id, x.uom) as pack_size,
    x.rate
  from jsonb_to_recordset(p_lines)
       as x(product_id uuid, uom app.uom_type, qty numeric, rate numeric);

  if exists (select 1 from pg_temp._ord_lines where qty is null or qty <= 0) then
    raise exception 'Every line needs a quantity above zero' using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._ord_lines
              group by product_id having count(*) > 1) then
    raise exception 'The same product appears more than once on this order'
      using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._ord_lines l
              join public.product p on p.id = l.product_id
             where not p.is_active) then
    raise exception 'An inactive product is on this order' using errcode = 'SA004';
  end if;

  v_doc_no := app.next_doc_no('SALES_ORDER');

  insert into public.sales_order
    (doc_no, party_id, order_date, status, remarks,
     submitted_at, expires_at, created_by)
  values
    (v_doc_no, p_party_id, p_order_date, 'SUBMITTED', p_remarks,
     now(), now() + make_interval(days => v_days), v_user)
  returning id into v_id;

  insert into public.sales_order_line
    (order_id, line_no, product_id, uom, qty, pack_size, rate)
  select v_id, line_no, product_id, uom, qty, pack_size,
         coalesce(rate, (select sale_rate from public.product where id = product_id))
    from pg_temp._ord_lines;

  perform app.reserve_for_order(v_id);

  return jsonb_build_object('order_id', v_id, 'doc_no', v_doc_no,
                            'expires_at', (select expires_at from public.sales_order where id = v_id));
end;
$$;

-- Replaces an order's lines wholesale. Only while nothing has been invoiced.
create or replace function public.modify_sales_order(
  p_order_id uuid,
  p_lines    jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_signed_in();
  v_status app.order_status;
begin
  select status into v_status from public.sales_order where id = p_order_id for update;

  if not found then
    raise exception 'Unknown order' using errcode = 'SA005';
  end if;

  if v_status <> 'SUBMITTED' then
    raise exception
      'This order is %, so it can no longer be modified. Cancel the pending quantity instead.',
      lower(replace(v_status::text, '_', ' '))
      using errcode = 'SA002';
  end if;

  if exists (select 1 from public.sales_invoice where order_id = p_order_id) then
    raise exception 'This order has already been invoiced and cannot be modified'
      using errcode = 'SA002';
  end if;

  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'An order needs at least one line' using errcode = 'SA004';
  end if;

  -- Give back what it currently holds, then re-reserve against the new lines.
  perform app.release_order_reservation(p_order_id);

  drop table if exists _mod_lines;
  create temp table _mod_lines on commit drop as
  select
    row_number() over ()                   as line_no,
    x.product_id,
    x.uom,
    x.qty,
    app.pack_size_for(x.product_id, x.uom) as pack_size,
    x.rate
  from jsonb_to_recordset(p_lines)
       as x(product_id uuid, uom app.uom_type, qty numeric, rate numeric);

  if exists (select 1 from pg_temp._mod_lines where qty is null or qty <= 0) then
    raise exception 'Every line needs a quantity above zero' using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._mod_lines
              group by product_id having count(*) > 1) then
    raise exception 'The same product appears more than once on this order'
      using errcode = 'SA004';
  end if;

  delete from public.sales_order_line where order_id = p_order_id;

  insert into public.sales_order_line
    (order_id, line_no, product_id, uom, qty, pack_size, rate)
  select p_order_id, line_no, product_id, uom, qty, pack_size,
         coalesce(rate, (select sale_rate from public.product where id = product_id))
    from pg_temp._mod_lines;

  perform app.reserve_for_order(p_order_id);

  update public.sales_order set updated_at = now() where id = p_order_id;

  return jsonb_build_object('order_id', p_order_id, 'modified', true);
end;
$$;

create or replace function public.cancel_sales_order(
  p_order_id uuid,
  p_reason   text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_signed_in();
  v_status app.order_status;
begin
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A cancellation reason is required' using errcode = 'SA004';
  end if;

  select status into v_status from public.sales_order where id = p_order_id for update;

  if not found then
    raise exception 'Unknown order' using errcode = 'SA005';
  end if;

  if v_status in ('CANCELLED', 'INVOICED') then
    raise exception 'This order is already %', lower(v_status::text)
      using errcode = 'SA002';
  end if;

  perform app.release_order_reservation(p_order_id);

  -- Whatever was never invoiced is now formally dropped.
  update public.sales_order_line
     set qty_cancelled_base = qty_cancelled_base + qty_pending_base
   where order_id = p_order_id
     and qty_pending_base > 0;

  update public.sales_order
     set status = 'CANCELLED', cancelled_at = now(),
         cancelled_by = v_user, cancel_reason = p_reason
   where id = p_order_id;

  return jsonb_build_object('order_id', p_order_id, 'status', 'CANCELLED');
end;
$$;

-- The daily job. Releases reservations on orders that were submitted and then
-- never invoiced within the window.
create or replace function public.expire_stale_orders()
returns integer
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_id    uuid;
  v_count integer := 0;
begin
  for v_id in
    select id from public.sales_order
     where status = 'SUBMITTED'
       and expires_at is not null
       and expires_at < now()
     order by expires_at
     for update skip locked
  loop
    perform app.release_order_reservation(v_id);

    update public.sales_order
       set status = 'EXPIRED', closed_at = now()
     where id = v_id;

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;

-- Puts an expired order back into play, if stock allows.
create or replace function public.reinstate_sales_order(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_back_office();
  v_status app.order_status;
  v_days   smallint := (app.settings()).reservation_expiry_days;
begin
  select status into v_status from public.sales_order where id = p_order_id for update;

  if not found then
    raise exception 'Unknown order' using errcode = 'SA005';
  end if;

  if v_status <> 'EXPIRED' then
    raise exception 'Only an expired order can be reinstated' using errcode = 'SA002';
  end if;

  update public.sales_order
     set status = 'SUBMITTED', closed_at = null,
         submitted_at = now(), expires_at = now() + make_interval(days => v_days)
   where id = p_order_id;

  -- Raises SA001 with the shortfall if stock has since gone.
  perform app.reserve_for_order(p_order_id);

  return jsonb_build_object('order_id', p_order_id, 'status', 'SUBMITTED');
end;
$$;

-- =============================================================================
-- SALES INVOICE
-- =============================================================================

create or replace function public.create_sales_invoice(
  p_invoice_date         date,
  p_lines                jsonb,
  p_order_id             uuid    default null,
  p_party_id             uuid    default null,
  p_bill_discount_amount numeric default 0,
  p_bill_discount_pct    numeric default null,
  p_remarks              text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user       uuid := app.require_back_office();
  v_doc_no     text;
  v_id         uuid;
  v_party      uuid;
  v_status     app.order_status;
  v_gross      numeric(14,2);
  v_line_disc  numeric(14,2);
  v_bill_disc  numeric(14,2);
  v_effective  numeric(14,2);
  v_net        numeric(14,2);
  v_round      numeric(14,2) := 0;
  v_ids        uuid[];
  v_shortfall  jsonb;
  v_over       jsonb;
begin
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'An invoice needs at least one line' using errcode = 'SA004';
  end if;

  -- Either invoice an order, or raise a direct counter sale for a named party.
  if p_order_id is not null then
    select party_id, status into v_party, v_status
      from public.sales_order where id = p_order_id for update;

    if not found then
      raise exception 'Unknown order' using errcode = 'SA005';
    end if;

    if v_status not in ('SUBMITTED', 'PARTIALLY_INVOICED') then
      raise exception 'Order is %, so it cannot be invoiced',
        lower(replace(v_status::text, '_', ' ')) using errcode = 'SA002';
    end if;
  else
    if p_party_id is null then
      raise exception 'A direct invoice needs a party' using errcode = 'SA004';
    end if;
    v_party := p_party_id;
  end if;

  -- ---------------------------------------------------------------------------
  -- Resolve each line: product, pack, quantities, line discount.
  -- ---------------------------------------------------------------------------
  drop table if exists _inv_lines;
  create temp table _inv_lines on commit drop as
  with raw as (
    select
      row_number() over ()   as line_no,
      x.order_line_id,
      coalesce(x.product_id, sol.product_id) as product_id,
      coalesce(x.uom, sol.uom, 'BASE')       as uom,
      x.qty,
      coalesce(x.rate, sol.rate)             as rate,
      x.line_discount_pct,
      x.line_discount_amount
    from jsonb_to_recordset(p_lines) as x(
           order_line_id        uuid,
           product_id           uuid,
           uom                  app.uom_type,
           qty                  numeric,
           rate                 numeric,
           line_discount_pct    numeric,
           line_discount_amount numeric)
    left join public.sales_order_line sol on sol.id = x.order_line_id
  ),
  sized as (
    select r.*,
           app.pack_size_for(r.product_id, r.uom) as pack_size
      from raw r
  )
  select
    s.line_no, s.order_line_id, s.product_id, s.uom, s.qty, s.pack_size, s.rate,
    s.qty * case when s.uom = 'PACK' then s.pack_size else 1 end as qty_base,
    round(s.qty * s.rate, 2)                                     as gross,
    s.line_discount_pct,
    coalesce(
      s.line_discount_amount,
      round(round(s.qty * s.rate, 2) * coalesce(s.line_discount_pct, 0) / 100, 2)
    )                                                            as line_discount_amount
  from sized s;

  if exists (select 1 from pg_temp._inv_lines where qty is null or qty <= 0) then
    raise exception 'Every line needs a quantity above zero' using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._inv_lines where rate is null) then
    raise exception 'Every line needs a rate' using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._inv_lines
              where line_discount_amount > gross) then
    raise exception 'A line discount is larger than the line itself'
      using errcode = 'SA004';
  end if;

  if p_order_id is not null
     and exists (select 1 from pg_temp._inv_lines where order_line_id is null) then
    raise exception 'Every line of an order-based invoice must reference an order line'
      using errcode = 'SA004';
  end if;

  -- ---------------------------------------------------------------------------
  -- Never invoice more than the order actually has pending.
  -- ---------------------------------------------------------------------------
  if p_order_id is not null then
    select jsonb_agg(jsonb_build_object(
             'product_name', p.name,
             'requested',    il.qty_base,
             'pending',      sol.qty_pending_base))
      into v_over
      from pg_temp._inv_lines il
      join public.sales_order_line sol on sol.id = il.order_line_id
      join public.product p on p.id = il.product_id
     where sol.order_id <> p_order_id
        or il.qty_base > sol.qty_pending_base;

    if v_over is not null then
      raise exception 'Invoiced quantity exceeds what the order has pending'
        using errcode = 'SA002', detail = v_over::text;
    end if;
  end if;

  -- ---------------------------------------------------------------------------
  -- Lock stock, then check it. Order matters: checking before locking is the
  -- classic oversell race.
  -- ---------------------------------------------------------------------------
  select array_agg(product_id) into v_ids from pg_temp._inv_lines;
  perform app.lock_products(v_ids);

  select jsonb_agg(jsonb_build_object(
           'product_code', p.code,
           'product_name', p.name,
           'base_uom',     p.base_uom,
           'requested',    t.needed,
           'on_hand',      ps.on_hand) order by p.name)
    into v_shortfall
    from (select product_id, sum(qty_base) as needed
            from pg_temp._inv_lines group by product_id) t
    join public.product       p  on p.id = t.product_id
    join public.product_stock ps on ps.product_id = t.product_id
   where t.needed > ps.on_hand;

  if v_shortfall is not null then
    raise exception 'Not enough stock on hand to raise this invoice'
      using errcode = 'SA001', detail = v_shortfall::text;
  end if;

  -- ---------------------------------------------------------------------------
  -- Totals, then allocate the bill discount across lines by largest remainder
  -- so the parts sum to the whole exactly.
  -- ---------------------------------------------------------------------------
  select coalesce(sum(gross), 0), coalesce(sum(line_discount_amount), 0)
    into v_gross, v_line_disc
    from pg_temp._inv_lines;

  v_bill_disc := coalesce(
    nullif(p_bill_discount_amount, 0),
    round((v_gross - v_line_disc) * coalesce(p_bill_discount_pct, 0) / 100, 2)
  );
  v_bill_disc := coalesce(v_bill_disc, 0);

  if v_bill_disc > (v_gross - v_line_disc) then
    raise exception 'The bill discount is larger than the invoice'
      using errcode = 'SA004';
  end if;

  drop table if exists _inv_alloc;
  create temp table _inv_alloc on commit drop as
  with base as (
    select line_no, (gross - line_discount_amount) as net
      from pg_temp._inv_lines
  ),
  tot as (select coalesce(sum(net), 0) as s from base),
  exact as (
    select b.line_no, b.net,
           case when t.s = 0 then 0 else v_bill_disc * b.net / t.s end as ex
      from base b cross join tot t
  ),
  floored as (
    select e.*,
           trunc(e.ex * 100) / 100                as flo,
           e.ex - trunc(e.ex * 100) / 100         as rem
      from exact e
  ),
  ranked as (
    select f.*,
           row_number() over (order by f.rem desc, f.net desc, f.line_no) as rk,
           round((v_bill_disc - sum(f.flo) over ()) * 100)::int           as spare
      from floored f
  )
  select line_no,
         (flo + case when rk <= spare then 0.01 else 0 end)::numeric(14,2) as alloc
    from ranked;

  select coalesce(sum(il.gross - il.line_discount_amount - a.alloc), 0)
    into v_effective
    from pg_temp._inv_lines il
    join pg_temp._inv_alloc a on a.line_no = il.line_no;

  if (app.settings()).round_invoice_total then
    v_net   := round(v_effective, 0);
    v_round := v_net - v_effective;
  else
    v_net   := v_effective;
    v_round := 0;
  end if;

  -- ---------------------------------------------------------------------------
  -- Write it
  -- ---------------------------------------------------------------------------
  v_doc_no := app.next_doc_no('SALES_INVOICE');

  insert into public.sales_invoice
    (doc_no, party_id, order_id, invoice_date, gross_total, line_discount_total,
     bill_discount_amount, round_off, net_total, remarks, created_by)
  values
    (v_doc_no, v_party, p_order_id, p_invoice_date, v_gross, v_line_disc,
     v_bill_disc, v_round, v_net, p_remarks, v_user)
  returning id into v_id;

  insert into public.sales_invoice_line
    (invoice_id, line_no, order_line_id, product_id, uom, qty, pack_size, rate,
     line_discount_pct, line_discount_amount, allocated_bill_discount)
  select v_id, il.line_no, il.order_line_id, il.product_id, il.uom, il.qty,
         il.pack_size, il.rate, il.line_discount_pct, il.line_discount_amount,
         a.alloc
    from pg_temp._inv_lines il
    join pg_temp._inv_alloc a on a.line_no = il.line_no;

  -- Stock out.
  insert into public.stock_ledger
    (product_id, movement_date, qty_out, rate, doc_type, doc_id, doc_line_id, created_by)
  select sil.product_id, p_invoice_date, sil.qty_base, sil.rate,
         'SALE', v_id, sil.id, v_user
    from public.sales_invoice_line sil
   where sil.invoice_id = v_id;

  -- ---------------------------------------------------------------------------
  -- Consume the order: the invoiced quantity stops being reserved and is now
  -- simply gone from on_hand, so availability is unchanged by invoicing.
  -- ---------------------------------------------------------------------------
  if p_order_id is not null then
    update public.sales_order_line sol
       set qty_invoiced_base = sol.qty_invoiced_base + il.qty_base
      from pg_temp._inv_lines il
     where sol.id = il.order_line_id;

    update public.product_stock ps
       set reserved   = greatest(ps.reserved - t.qty, 0),
           updated_at = now()
      from (select product_id, sum(qty_base) as qty
              from pg_temp._inv_lines group by product_id) t
     where ps.product_id = t.product_id;

    update public.sales_order so
       set status = case
                      when not exists (select 1 from public.sales_order_line
                                        where order_id = p_order_id
                                          and qty_pending_base > 0)
                      then 'INVOICED'::app.order_status
                      else 'PARTIALLY_INVOICED'::app.order_status
                    end,
           closed_at = case
                         when not exists (select 1 from public.sales_order_line
                                           where order_id = p_order_id
                                             and qty_pending_base > 0)
                         then now() else null
                       end
     where so.id = p_order_id;
  end if;

  return jsonb_build_object(
    'invoice_id', v_id, 'doc_no', v_doc_no,
    'gross_total', v_gross, 'bill_discount', v_bill_disc,
    'round_off', v_round, 'net_total', v_net);
end;
$$;

-- -----------------------------------------------------------------------------
-- Cancellation
--
-- p_lines null  -> cancel everything still standing on the invoice
-- p_lines given -> [{"invoice_line_id": "...", "qty_base": 5}, ...]
-- -----------------------------------------------------------------------------

create or replace function public.cancel_sales_invoice(
  p_invoice_id uuid,
  p_reason     text,
  p_lines      jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user      uuid := app.require_back_office();
  v_inv       public.sales_invoice%rowtype;
  v_doc_no    text;
  v_can_id    uuid;
  v_value     numeric(14,2);
  v_is_full   boolean;
  v_ids       uuid[];
  v_allocated numeric(14,2);
  v_excess    numeric(14,2);
  v_released  numeric(14,2) := 0;
  r           record;
begin
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A cancellation reason is required' using errcode = 'SA004';
  end if;

  select * into v_inv from public.sales_invoice where id = p_invoice_id for update;

  if not found then
    raise exception 'Unknown invoice' using errcode = 'SA005';
  end if;

  if v_inv.status = 'CANCELLED' then
    raise exception 'This invoice is already fully cancelled' using errcode = 'SA002';
  end if;

  -- ---------------------------------------------------------------------------
  -- What is being cancelled, and what it is worth.
  --
  -- Value is derived from the cumulative cancelled quantity rather than this
  -- slice alone, so a series of partial cancels that ends up covering the whole
  -- line credits back exactly the line's value, with no rounding residue.
  -- ---------------------------------------------------------------------------
  drop table if exists _can_lines;
  create temp table _can_lines on commit drop as
  with picked as (
    select
      sil.id                as invoice_line_id,
      sil.product_id,
      sil.qty_base,
      sil.effective_amount,
      sil.qty_cancelled_base                        as already_base,
      least(coalesce(x.qty_base, sil.qty_base - sil.qty_cancelled_base),
            sil.qty_base - sil.qty_cancelled_base)  as cancel_base
    from public.sales_invoice_line sil
    left join lateral (
      select (e ->> 'qty_base')::numeric as qty_base
        from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) e
       where (e ->> 'invoice_line_id')::uuid = sil.id
    ) x on true
    where sil.invoice_id = p_invoice_id
      and (p_lines is null or x.qty_base is not null)
      and sil.qty_base > sil.qty_cancelled_base
  )
  select
    p.*,
    -- Pro-rate from the cumulative cancelled quantity rather than this slice,
    -- so partial cancels that eventually cover the line credit back exactly
    -- the line's value with no rounding residue.
    (round(p.effective_amount * (p.already_base + p.cancel_base) / p.qty_base, 2)
     - round(p.effective_amount * p.already_base / p.qty_base, 2))::numeric(14,2)
      as value_now
  from picked p
  where p.cancel_base > 0;

  if not exists (select 1 from pg_temp._can_lines) then
    raise exception 'Nothing on this invoice is left to cancel' using errcode = 'SA002';
  end if;

  select coalesce(sum(value_now), 0) into v_value from pg_temp._can_lines;

  -- Is the whole invoice now accounted for?
  v_is_full := not exists (
    select 1
      from public.sales_invoice_line sil
      left join pg_temp._can_lines cl on cl.invoice_line_id = sil.id
     where sil.invoice_id = p_invoice_id
       and sil.qty_base > sil.qty_cancelled_base + coalesce(cl.cancel_base, 0)
  );

  -- A fully cancelled invoice must give back its rounding adjustment too,
  -- otherwise cancelled_value could never equal net_total.
  if v_is_full then
    v_value := v_inv.net_total - v_inv.cancelled_value;
  end if;

  -- ---------------------------------------------------------------------------
  -- Release any payment this cancellation would strand, newest allocation
  -- first. The money returns to the party's on-account balance by virtue of
  -- no longer being allocated.
  -- ---------------------------------------------------------------------------
  select coalesce(sum(amount), 0) into v_allocated
    from public.credit_allocation where invoice_id = p_invoice_id;

  v_excess := v_allocated - (v_inv.net_total - v_inv.cancelled_value - v_value);

  if v_excess > 0 then
    for r in
      select id, amount from public.credit_allocation
       where invoice_id = p_invoice_id
       order by created_at desc, id desc
    loop
      exit when v_excess <= 0;

      if r.amount <= v_excess then
        delete from public.credit_allocation where id = r.id;
        v_excess   := v_excess - r.amount;
        v_released := v_released + r.amount;
      else
        update public.credit_allocation
           set amount = r.amount - v_excess where id = r.id;
        v_released := v_released + v_excess;
        v_excess   := 0;
      end if;
    end loop;
  end if;

  -- ---------------------------------------------------------------------------
  -- Write the cancellation document
  -- ---------------------------------------------------------------------------
  v_doc_no := app.next_doc_no('INVOICE_CANCELLATION');

  insert into public.invoice_cancellation
    (doc_no, invoice_id, cancellation_date, is_full, cancelled_value, reason, created_by)
  values
    (v_doc_no, p_invoice_id, current_date, v_is_full, v_value, p_reason, v_user)
  returning id into v_can_id;

  insert into public.invoice_cancellation_line
    (cancellation_id, invoice_line_id, product_id, qty_base, cancelled_value)
  select v_can_id, invoice_line_id, product_id, cancel_base, value_now
    from pg_temp._can_lines;

  -- Stock back in, as free stock. It does not return to the order's reservation.
  select array_agg(distinct product_id) into v_ids from pg_temp._can_lines;
  perform app.lock_products(v_ids);

  insert into public.stock_ledger
    (product_id, movement_date, qty_in, rate, doc_type, doc_id, doc_line_id, created_by)
  select cl.product_id, current_date, cl.cancel_base, 0,
         'SALE_CANCEL', v_can_id, cl.invoice_line_id, v_user
    from pg_temp._can_lines cl;

  update public.sales_invoice_line sil
     set qty_cancelled_base = sil.qty_cancelled_base + cl.cancel_base
    from pg_temp._can_lines cl
   where sil.id = cl.invoice_line_id;

  update public.sales_invoice
     set cancelled_value = cancelled_value + v_value,
         status = case
                    when v_is_full then 'CANCELLED'::app.invoice_status
                    else 'PARTIALLY_CANCELLED'::app.invoice_status
                  end
   where id = p_invoice_id;

  return jsonb_build_object(
    'cancellation_id', v_can_id, 'doc_no', v_doc_no,
    'cancelled_value', v_value, 'is_full', v_is_full,
    'payment_released_to_on_account', v_released);
end;
$$;

-- =============================================================================
-- Grants
-- =============================================================================

grant execute on function
  public.post_purchase(uuid, date, jsonb, numeric, text, date, text),
  public.create_sales_order(uuid, date, jsonb, text),
  public.modify_sales_order(uuid, jsonb),
  public.cancel_sales_order(uuid, text),
  public.reinstate_sales_order(uuid),
  public.create_sales_invoice(date, jsonb, uuid, uuid, numeric, numeric, text),
  public.cancel_sales_invoice(uuid, text, jsonb),
  public.post_opening_stock()
to authenticated;

-- expire_stale_orders is for the scheduler, not for clients.
revoke all on function public.expire_stale_orders() from authenticated;

-- >>>>>>>>>>>>>>>>>>>>  014_money_functions.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 014_money_functions.sql
-- Sales returns, receipts, and the allocation of credits against invoices.
--
-- Policy decision: allocation is ALWAYS manual. Creating a receipt settles
-- nothing on its own; someone chooses which invoices it pays. Money therefore
-- never lands on an invoice by accident, at the cost of a second step.
-- =============================================================================

-- =============================================================================
-- SALES RETURN
-- =============================================================================

create or replace function public.post_sales_return(
  p_party_id    uuid,
  p_return_date date,
  p_lines       jsonb,
  p_reason      text,
  p_invoice_id  uuid default null,
  p_remarks     text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user     uuid := app.require_back_office();
  v_doc_no   text;
  v_id       uuid;
  v_total    numeric(14,2);
  v_restock  numeric(14,4);
begin
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A return needs a reason' using errcode = 'SA004';
  end if;

  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'A return needs at least one line' using errcode = 'SA004';
  end if;

  if p_invoice_id is not null
     and not exists (select 1 from public.sales_invoice
                      where id = p_invoice_id and party_id = p_party_id) then
    raise exception 'That invoice does not belong to this party'
      using errcode = 'SA004';
  end if;

  drop table if exists _ret_lines;
  create temp table _ret_lines on commit drop as
  select
    row_number() over ()                        as line_no,
    x.product_id,
    x.invoice_line_id,
    coalesce(x.uom, 'BASE')                     as uom,
    x.qty,
    app.pack_size_for(x.product_id, coalesce(x.uom, 'BASE')) as pack_size,
    x.rate,
    coalesce(x.restock, true)                   as restock
  from jsonb_to_recordset(p_lines) as x(
         product_id      uuid,
         invoice_line_id uuid,
         uom             app.uom_type,
         qty             numeric,
         rate            numeric,
         restock         boolean);

  if exists (select 1 from pg_temp._ret_lines where qty is null or qty <= 0) then
    raise exception 'Every return line needs a quantity above zero'
      using errcode = 'SA004';
  end if;

  if exists (select 1 from pg_temp._ret_lines where rate is null or rate < 0) then
    raise exception 'Every return line needs a rate' using errcode = 'SA004';
  end if;

  select coalesce(sum(round(qty * rate, 2)), 0) into v_total from pg_temp._ret_lines;

  v_doc_no := app.next_doc_no('SALES_RETURN');

  insert into public.sales_return
    (doc_no, party_id, invoice_id, return_date, total_value, reason, remarks, created_by)
  values
    (v_doc_no, p_party_id, p_invoice_id, p_return_date, v_total,
     p_reason, p_remarks, v_user)
  returning id into v_id;

  insert into public.sales_return_line
    (return_id, line_no, product_id, invoice_line_id, uom, qty, pack_size, rate, restock)
  select v_id, line_no, product_id, invoice_line_id, uom, qty, pack_size, rate, restock
    from pg_temp._ret_lines;

  -- Only resaleable goods go back into stock. The rest are written off: the
  -- customer is still credited, but the goods are gone.
  insert into public.stock_ledger
    (product_id, movement_date, qty_in, rate, doc_type, doc_id, doc_line_id, created_by)
  select srl.product_id, p_return_date, srl.qty_base, srl.rate,
         'SALE_RETURN', v_id, srl.id, v_user
    from public.sales_return_line srl
   where srl.return_id = v_id
     and srl.restock;

  select coalesce(sum(qty_base), 0) into v_restock
    from public.sales_return_line where return_id = v_id and restock;

  return jsonb_build_object(
    'return_id', v_id, 'doc_no', v_doc_no,
    'total_value', v_total, 'restocked_qty', v_restock,
    'note', 'This credit is not applied to any invoice until it is allocated.');
end;
$$;

create or replace function public.cancel_sales_return(
  p_return_id uuid,
  p_reason    text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user  uuid := app.require_back_office();
  v_ret   public.sales_return%rowtype;
  v_ids   uuid[];
  v_short jsonb;
begin
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A cancellation reason is required' using errcode = 'SA004';
  end if;

  select * into v_ret from public.sales_return where id = p_return_id for update;

  if not found then
    raise exception 'Unknown sales return' using errcode = 'SA005';
  end if;

  if v_ret.status = 'CANCELLED' then
    raise exception 'This return is already cancelled' using errcode = 'SA002';
  end if;

  -- Taking the goods back out needs them to still be there. If they have been
  -- resold in the meantime, say so plainly rather than letting stock go wrong.
  select array_agg(distinct product_id) into v_ids
    from public.sales_return_line where return_id = p_return_id and restock;

  perform app.lock_products(coalesce(v_ids, '{}'::uuid[]));

  select jsonb_agg(jsonb_build_object(
           'product_code', p.code,
           'product_name', p.name,
           'needed',       t.qty,
           'on_hand',      ps.on_hand))
    into v_short
    from (select product_id, sum(qty_base) as qty
            from public.sales_return_line
           where return_id = p_return_id and restock
           group by product_id) t
    join public.product       p  on p.id = t.product_id
    join public.product_stock ps on ps.product_id = t.product_id
   where t.qty > ps.on_hand;

  if v_short is not null then
    raise exception
      'Cannot cancel this return: the goods have already been sold again'
      using errcode = 'SA001', detail = v_short::text;
  end if;

  insert into public.stock_ledger
    (product_id, movement_date, qty_out, rate, doc_type, doc_id, doc_line_id, created_by)
  select srl.product_id, current_date, srl.qty_base, srl.rate,
         'SALE_RETURN_CANCEL', p_return_id, srl.id, v_user
    from public.sales_return_line srl
   where srl.return_id = p_return_id
     and srl.restock;

  -- Its credit stops existing, so anything it was paying goes back to owing.
  delete from public.credit_allocation where sales_return_id = p_return_id;

  update public.sales_return
     set status = 'CANCELLED', cancelled_at = now(),
         cancelled_by = v_user, cancel_reason = p_reason
   where id = p_return_id;

  return jsonb_build_object('return_id', p_return_id, 'status', 'CANCELLED');
end;
$$;

-- =============================================================================
-- RECEIPT
-- =============================================================================

create or replace function public.create_receipt(
  p_party_id        uuid,
  p_receipt_date    date,
  p_mode            app.payment_mode,
  p_amount          numeric,
  p_reference_no    text default null,
  p_instrument_date date default null,
  p_bank_name       text default null,
  p_collected_by    uuid default null,
  p_remarks         text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_back_office();
  v_doc_no text;
  v_id     uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'A receipt needs an amount above zero' using errcode = 'SA004';
  end if;

  if not exists (select 1 from public.party where id = p_party_id) then
    raise exception 'Unknown party' using errcode = 'SA005';
  end if;

  if p_collected_by is not null
     and not exists (select 1 from public.app_user where id = p_collected_by) then
    raise exception 'Unknown collector' using errcode = 'SA005';
  end if;

  v_doc_no := app.next_doc_no('RECEIPT');

  insert into public.receipt
    (doc_no, party_id, receipt_date, mode, amount, reference_no,
     instrument_date, bank_name, clearing_status, collected_by, remarks, created_by)
  values
    (v_doc_no, p_party_id, p_receipt_date, p_mode, p_amount, p_reference_no,
     p_instrument_date, p_bank_name,
     case when p_mode = 'CHEQUE' then 'PENDING' else null end,
     coalesce(p_collected_by, v_user), p_remarks, v_user)
  returning id into v_id;

  return jsonb_build_object(
    'receipt_id', v_id, 'doc_no', v_doc_no, 'amount', p_amount,
    'unallocated', p_amount,
    'note', 'Not applied to any invoice yet. Allocate it to settle invoices.');
end;
$$;

create or replace function public.cancel_receipt(
  p_receipt_id uuid,
  p_reason     text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user   uuid := app.require_back_office();
  v_status app.doc_status;
begin
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A cancellation reason is required' using errcode = 'SA004';
  end if;

  select status into v_status from public.receipt where id = p_receipt_id for update;

  if not found then
    raise exception 'Unknown receipt' using errcode = 'SA005';
  end if;

  if v_status = 'CANCELLED' then
    raise exception 'This receipt is already cancelled' using errcode = 'SA002';
  end if;

  delete from public.credit_allocation where receipt_id = p_receipt_id;

  update public.receipt
     set status = 'CANCELLED', cancelled_at = now(),
         cancelled_by = v_user, cancel_reason = p_reason
   where id = p_receipt_id;

  return jsonb_build_object('receipt_id', p_receipt_id, 'status', 'CANCELLED');
end;
$$;

-- -----------------------------------------------------------------------------
-- Cheque clearing
--
-- A bounced cheque keeps its receipt, for the record, but stops being money:
-- its allocations are reversed and the invoices go back into outstanding.
-- -----------------------------------------------------------------------------

create or replace function public.set_cheque_status(
  p_receipt_id uuid,
  p_status     text,
  p_remarks    text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user     uuid := app.require_back_office();
  v_rct      public.receipt%rowtype;
  v_reversed numeric(14,2) := 0;
begin
  if p_status not in ('PENDING', 'CLEARED', 'BOUNCED') then
    raise exception 'Cheque status must be PENDING, CLEARED or BOUNCED'
      using errcode = 'SA004';
  end if;

  select * into v_rct from public.receipt where id = p_receipt_id for update;

  if not found then
    raise exception 'Unknown receipt' using errcode = 'SA005';
  end if;

  if v_rct.mode <> 'CHEQUE' then
    raise exception 'Only a cheque receipt has a clearing status'
      using errcode = 'SA002';
  end if;

  if v_rct.status = 'CANCELLED' then
    raise exception 'This receipt is cancelled' using errcode = 'SA002';
  end if;

  if p_status = 'BOUNCED' then
    select coalesce(sum(amount), 0) into v_reversed
      from public.credit_allocation where receipt_id = p_receipt_id;

    delete from public.credit_allocation where receipt_id = p_receipt_id;
  end if;

  update public.receipt
     set clearing_status = p_status,
         remarks = coalesce(p_remarks, remarks)
   where id = p_receipt_id;

  return jsonb_build_object(
    'receipt_id', p_receipt_id, 'clearing_status', p_status,
    'allocations_reversed', v_reversed);
end;
$$;

-- =============================================================================
-- ALLOCATION
--
-- One call sets the allocations for a single credit. Whatever is passed becomes
-- the complete picture for that credit: invoices not mentioned are released.
-- Passing an empty array unallocates it entirely.
--
-- Input: [{"invoice_id": "...", "amount": 1000.00}, ...]
-- =============================================================================

create or replace function public.allocate_credit(
  p_allocations    jsonb,
  p_receipt_id     uuid default null,
  p_sales_return_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user      uuid := app.require_back_office();
  v_party     uuid;
  v_limit     numeric(14,2);
  v_requested numeric(14,2);
  v_bad       jsonb;
begin
  if num_nonnulls(p_receipt_id, p_sales_return_id) <> 1 then
    raise exception 'Allocate from exactly one receipt or one sales return'
      using errcode = 'SA004';
  end if;

  if jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then
    raise exception 'Allocations must be an array' using errcode = 'SA004';
  end if;

  -- Identify the credit and check it is still live.
  if p_receipt_id is not null then
    select party_id, amount into v_party, v_limit
      from public.receipt
     where id = p_receipt_id and status = 'ACTIVE'
     for update;

    if not found then
      raise exception 'Unknown or cancelled receipt' using errcode = 'SA005';
    end if;

    if exists (select 1 from public.receipt
                where id = p_receipt_id and clearing_status = 'BOUNCED') then
      raise exception 'A bounced cheque cannot settle invoices'
        using errcode = 'SA002';
    end if;
  else
    select party_id, total_value into v_party, v_limit
      from public.sales_return
     where id = p_sales_return_id and status = 'ACTIVE'
     for update;

    if not found then
      raise exception 'Unknown or cancelled sales return' using errcode = 'SA005';
    end if;
  end if;

  drop table if exists _alloc;
  create temp table _alloc on commit drop as
  select x.invoice_id, round(x.amount, 2) as amount
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
         as x(invoice_id uuid, amount numeric)
   where coalesce(x.amount, 0) > 0;

  if exists (select 1 from pg_temp._alloc group by invoice_id having count(*) > 1) then
    raise exception 'The same invoice appears twice in this allocation'
      using errcode = 'SA004';
  end if;

  -- Money only moves between documents of the same party.
  select jsonb_agg(jsonb_build_object('invoice_id', a.invoice_id))
    into v_bad
    from pg_temp._alloc a
    left join public.sales_invoice si on si.id = a.invoice_id
   where si.id is null or si.party_id <> v_party;

  if v_bad is not null then
    raise exception 'An invoice in this allocation is unknown or belongs to another party'
      using errcode = 'SA004', detail = v_bad::text;
  end if;

  select coalesce(sum(amount), 0) into v_requested from pg_temp._alloc;

  if v_requested > v_limit then
    raise exception 'Allocating % exceeds the credit of %', v_requested, v_limit
      using errcode = 'SA004';
  end if;

  -- Replace this credit's allocations wholesale.
  delete from public.credit_allocation
   where (p_receipt_id is not null and receipt_id = p_receipt_id)
      or (p_sales_return_id is not null and sales_return_id = p_sales_return_id);

  insert into public.credit_allocation
    (receipt_id, sales_return_id, invoice_id, amount, created_by)
  select p_receipt_id, p_sales_return_id, a.invoice_id, a.amount, v_user
    from pg_temp._alloc a;

  -- The deferred triggers verify at COMMIT that nothing over-allocates an
  -- invoice; this is here so the caller gets the number back immediately.
  return jsonb_build_object(
    'allocated',   v_requested,
    'unallocated', v_limit - v_requested,
    'invoices',    (select count(*) from pg_temp._alloc));
end;
$$;

-- =============================================================================
-- Grants
-- =============================================================================

grant execute on function
  public.post_sales_return(uuid, date, jsonb, text, uuid, text),
  public.cancel_sales_return(uuid, text),
  public.create_receipt(uuid, date, app.payment_mode, numeric, text, date, text, uuid, text),
  public.cancel_receipt(uuid, text),
  public.set_cheque_status(uuid, text, text),
  public.allocate_credit(jsonb, uuid, uuid)
to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  015_reports.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 015_reports.sql
-- Reporting views.
--
-- All are security_invoker, so a rep sees exactly what RLS allows them to see
-- and no more. A view without it becomes a hole straight through RLS.
--
-- What counts as money, consistently across every view below:
--   * an invoice is owed at net_total minus whatever has been cancelled
--   * a receipt is a credit unless it is cancelled or its cheque bounced
--   * a sales return is a credit unless it is cancelled
--   * a PENDING cheque is treated as money, because it has been received;
--     v_pending_cheques exists so that exposure is visible separately
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Live credits: receipts and returns in one shape, so every downstream view
-- treats them identically.
-- -----------------------------------------------------------------------------

create or replace view public.v_credit as
select
  r.id             as credit_id,
  'RECEIPT'::text  as credit_type,
  r.doc_no,
  r.party_id,
  r.receipt_date   as credit_date,
  r.amount         as credit_amount,
  r.mode::text     as mode,
  r.collected_by
from public.receipt r
where r.status = 'ACTIVE'
  and coalesce(r.clearing_status, 'CLEARED') <> 'BOUNCED'

union all

select
  sr.id,
  'RETURN',
  sr.doc_no,
  sr.party_id,
  sr.return_date,
  sr.total_value,
  'GOODS RETURNED',
  null
from public.sales_return sr
where sr.status = 'ACTIVE';

-- -----------------------------------------------------------------------------
-- Invoice outstanding
-- -----------------------------------------------------------------------------

create or replace view public.v_invoice_outstanding as
select
  si.id            as invoice_id,
  si.doc_no,
  si.party_id,
  p.code           as party_code,
  p.name           as party_name,
  p.route_id,
  rt.name          as route_name,
  si.invoice_date,
  si.net_total,
  si.cancelled_value,
  si.effective_total,
  coalesce(ca.allocated, 0)                     as settled,
  si.effective_total - coalesce(ca.allocated, 0) as outstanding,
  current_date - si.invoice_date                as days_outstanding,
  si.status
from public.sales_invoice si
join public.party p  on p.id  = si.party_id
join public.route rt on rt.id = p.route_id
left join (
  select invoice_id, sum(amount) as allocated
    from public.credit_allocation
   group by invoice_id
) ca on ca.invoice_id = si.id
where si.status <> 'CANCELLED';

-- -----------------------------------------------------------------------------
-- Ageing
--
-- Buckets measured in days from the invoice date: 0-15, 16-30, 31-45, 46+.
-- -----------------------------------------------------------------------------

create or replace view public.v_ageing as
select
  io.*,
  case
    when io.days_outstanding <= 15 then '0-15'
    when io.days_outstanding <= 30 then '16-30'
    when io.days_outstanding <= 45 then '31-45'
    else '46+'
  end as bucket
from public.v_invoice_outstanding io
where io.outstanding > 0;

create or replace view public.v_ageing_by_party as
select
  party_id, party_code, party_name, route_id, route_name,
  sum(outstanding)                                          as total_outstanding,
  sum(outstanding) filter (where bucket = '0-15')  as b_0_15,
  sum(outstanding) filter (where bucket = '16-30') as b_16_30,
  sum(outstanding) filter (where bucket = '31-45') as b_31_45,
  sum(outstanding) filter (where bucket = '46+')   as b_46_plus,
  max(days_outstanding)                                     as oldest_days,
  count(*)                                                  as open_invoices
from public.v_ageing
group by party_id, party_code, party_name, route_id, route_name;

create or replace view public.v_ageing_by_route as
select
  route_id, route_name,
  sum(total_outstanding) as total_outstanding,
  sum(b_0_15)            as b_0_15,
  sum(b_16_30)           as b_16_30,
  sum(b_31_45)           as b_31_45,
  sum(b_46_plus)         as b_46_plus,
  count(*)               as parties_owing
from public.v_ageing_by_party
group by route_id, route_name;

-- -----------------------------------------------------------------------------
-- Unallocated credit — money received but not yet applied to any invoice.
--
-- With manual allocation this is the queue Accounts works through, so it is a
-- screen in its own right, not just a number.
-- -----------------------------------------------------------------------------

create or replace view public.v_unallocated_credit as
select
  c.credit_id, c.credit_type, c.doc_no, c.party_id,
  p.code  as party_code,
  p.name  as party_name,
  c.credit_date, c.mode,
  c.credit_amount,
  coalesce(a.allocated, 0)                  as allocated,
  c.credit_amount - coalesce(a.allocated, 0) as unallocated,
  current_date - c.credit_date              as days_waiting
from public.v_credit c
join public.party p on p.id = c.party_id
left join (
  select coalesce(receipt_id, sales_return_id) as credit_id, sum(amount) as allocated
    from public.credit_allocation
   group by coalesce(receipt_id, sales_return_id)
) a on a.credit_id = c.credit_id
where c.credit_amount - coalesce(a.allocated, 0) > 0;

-- -----------------------------------------------------------------------------
-- Party balance
--
--   opening + what is still owed on invoices - credit not yet applied
--
-- Which is the same as: opening + invoices - credits. The test suite proves
-- both routes agree, because a divergence here means money has gone missing.
-- -----------------------------------------------------------------------------

create or replace view public.v_party_balance as
select
  p.id                as party_id,
  p.code              as party_code,
  p.name              as party_name,
  p.route_id,
  rt.name             as route_name,
  p.credit_limit,
  p.credit_days,
  p.opening_balance,
  coalesce(inv.owed, 0)                          as invoice_outstanding,
  coalesce(cr.unapplied, 0)                      as on_account,
  p.opening_balance + coalesce(inv.owed, 0) - coalesce(cr.unapplied, 0) as balance,
  case
    when p.credit_limit > 0
     and p.opening_balance + coalesce(inv.owed, 0) - coalesce(cr.unapplied, 0)
         > p.credit_limit
    then true else false
  end                 as over_credit_limit,
  p.is_active
from public.party p
join public.route rt on rt.id = p.route_id
left join (
  select party_id, sum(outstanding) as owed
    from public.v_invoice_outstanding
   group by party_id
) inv on inv.party_id = p.id
left join (
  select party_id, sum(unallocated) as unapplied
    from public.v_unallocated_credit
   group by party_id
) cr on cr.party_id = p.id;

-- -----------------------------------------------------------------------------
-- Party ledger
--
-- One row per document, oldest first, with a running balance. Invoices are
-- shown at their issued value and cancellations as separate credit lines, so
-- the ledger reads the way a paper one would rather than silently restating
-- history.
-- -----------------------------------------------------------------------------

create or replace view public.v_party_ledger as
with entries as (
  select p.id as party_id, p.opening_balance_date as entry_date, 0 as sort_key,
         'OPENING'::text as doc_type, 'Opening balance'::text as doc_no,
         p.opening_balance as debit, 0::numeric as credit, null::uuid as doc_id
    from public.party p
   where p.opening_balance <> 0

  union all

  select si.party_id, si.invoice_date, 1, 'INVOICE', si.doc_no,
         si.net_total, 0, si.id
    from public.sales_invoice si

  union all

  select si.party_id, ic.cancellation_date, 2, 'CANCELLATION', ic.doc_no,
         0, ic.cancelled_value, ic.id
    from public.invoice_cancellation ic
    join public.sales_invoice si on si.id = ic.invoice_id

  union all

  select sr.party_id, sr.return_date, 3, 'RETURN', sr.doc_no,
         0, sr.total_value, sr.id
    from public.sales_return sr
   where sr.status = 'ACTIVE'

  union all

  select r.party_id, r.receipt_date, 4, 'RECEIPT', r.doc_no,
         0, r.amount, r.id
    from public.receipt r
   where r.status = 'ACTIVE'
     and coalesce(r.clearing_status, 'CLEARED') <> 'BOUNCED'
)
select
  e.party_id,
  p.code as party_code,
  p.name as party_name,
  e.entry_date,
  e.doc_type,
  e.doc_no,
  e.doc_id,
  e.debit,
  e.credit,
  sum(e.debit - e.credit) over (
    partition by e.party_id
    order by e.entry_date, e.sort_key, e.doc_no
    rows between unbounded preceding and current row
  ) as running_balance
from entries e
join public.party p on p.id = e.party_id;

-- -----------------------------------------------------------------------------
-- Sales register
-- -----------------------------------------------------------------------------

create or replace view public.v_sales_register as
select
  si.id           as invoice_id,
  si.doc_no,
  si.invoice_date,
  p.code          as party_code,
  p.name          as party_name,
  rt.name         as route_name,
  u.full_name     as created_by_name,
  so.doc_no       as order_no,
  rep.full_name   as rep_name,
  si.gross_total,
  si.line_discount_total,
  si.bill_discount_amount,
  si.round_off,
  si.net_total,
  si.cancelled_value,
  si.effective_total,
  si.status
from public.sales_invoice si
join public.party p       on p.id  = si.party_id
join public.route rt      on rt.id = p.route_id
left join public.app_user u   on u.id = si.created_by
left join public.sales_order so on so.id = si.order_id
left join public.app_user rep on rep.id = so.created_by;

-- -----------------------------------------------------------------------------
-- Product-wise sales and margin
--
-- NOTE: margin uses the product's CURRENT purchase_rate, not the cost at the
-- time of sale, which the schema does not yet capture. It is therefore an
-- estimate and will drift if buying prices move. Treat it as indicative until
-- a costing method is chosen.
-- -----------------------------------------------------------------------------

create or replace view public.v_product_sales as
select
  pr.id            as product_id,
  pr.code          as product_code,
  pr.name          as product_name,
  pg.name          as group_name,
  pr.base_uom,
  si.invoice_date,
  sum(sil.qty_base - sil.qty_cancelled_base)     as qty_sold_base,
  sum(sil.effective_amount
      - round(sil.effective_amount * sil.qty_cancelled_base
              / nullif(sil.qty_base, 0), 2))     as net_sales,
  sum((sil.qty_base - sil.qty_cancelled_base) * pr.purchase_rate) as est_cost,
  sum(sil.effective_amount
      - round(sil.effective_amount * sil.qty_cancelled_base
              / nullif(sil.qty_base, 0), 2))
    - sum((sil.qty_base - sil.qty_cancelled_base) * pr.purchase_rate)
                                                  as est_margin
from public.sales_invoice_line sil
join public.sales_invoice si on si.id = sil.invoice_id
join public.product pr       on pr.id = sil.product_id
join public.product_group pg on pg.id = pr.group_id
where si.status <> 'CANCELLED'
group by pr.id, pr.code, pr.name, pg.name, pr.base_uom, si.invoice_date;

-- -----------------------------------------------------------------------------
-- Collections
--
-- days_in_transit is the gap between the date the customer paid and the date
-- the receipt was entered. For cash a rep collected and later handed over,
-- that gap is how long the money sat with them. It is the only visibility the
-- system has into that, because Accounts enters receipts on handover; if a
-- rep never hands cash over, no receipt exists and nothing here will show it.
-- -----------------------------------------------------------------------------

create or replace view public.v_collection_report as
select
  r.id            as receipt_id,
  r.doc_no,
  r.receipt_date,
  r.created_at::date as entered_on,
  (r.created_at::date - r.receipt_date) as days_in_transit,
  p.code          as party_code,
  p.name          as party_name,
  rt.name         as route_name,
  r.mode,
  r.amount,
  r.clearing_status,
  coll.full_name  as collected_by_name,
  coll.role       as collected_by_role,
  ent.full_name   as entered_by_name,
  r.status
from public.receipt r
join public.party p       on p.id  = r.party_id
join public.route rt      on rt.id = p.route_id
left join public.app_user coll on coll.id = r.collected_by
left join public.app_user ent  on ent.id  = r.created_by;

create or replace view public.v_collection_by_collector as
select
  coalesce(coll.full_name, 'Unattributed') as collected_by_name,
  r.collected_by,
  r.receipt_date,
  r.mode,
  count(*)                                 as receipts,
  sum(r.amount)                            as collected,
  round(avg(r.created_at::date - r.receipt_date), 1) as avg_days_in_transit
from public.receipt r
left join public.app_user coll on coll.id = r.collected_by
where r.status = 'ACTIVE'
group by coll.full_name, r.collected_by, r.receipt_date, r.mode;

-- -----------------------------------------------------------------------------
-- Pending cheques
-- -----------------------------------------------------------------------------

create or replace view public.v_pending_cheques as
select
  r.id           as receipt_id,
  r.doc_no,
  r.receipt_date,
  r.instrument_date,
  r.reference_no as cheque_no,
  r.bank_name,
  p.code         as party_code,
  p.name         as party_name,
  r.amount,
  current_date - coalesce(r.instrument_date, r.receipt_date) as days_since_instrument
from public.receipt r
join public.party p on p.id = r.party_id
where r.mode = 'CHEQUE'
  and r.clearing_status = 'PENDING'
  and r.status = 'ACTIVE';

-- -----------------------------------------------------------------------------
-- Stock
-- -----------------------------------------------------------------------------

create or replace view public.v_stock_report as
select
  pr.id        as product_id,
  pr.code      as product_code,
  pr.name      as product_name,
  pg.name      as group_name,
  pr.base_uom,
  pr.pack_uom,
  pr.pack_size,
  ps.on_hand,
  ps.reserved,
  ps.available,
  case when pr.pack_size > 1
       then floor(ps.available / pr.pack_size) else null end as available_packs,
  pr.sale_rate,
  pr.purchase_rate,
  ps.on_hand * pr.purchase_rate as stock_value_at_cost,
  ps.updated_at,
  pr.is_active
from public.product pr
join public.product_group pg on pg.id = pr.group_id
join public.product_stock ps on ps.product_id = pr.id;

-- Orders holding stock that is about to be released.
create or replace view public.v_pending_orders as
select
  so.id        as order_id,
  so.doc_no,
  so.order_date,
  so.status,
  so.expires_at,
  p.code       as party_code,
  p.name       as party_name,
  rt.name      as route_name,
  rep.full_name as rep_name,
  count(sol.id)                                   as lines,
  sum(sol.qty_pending_base)                       as qty_pending_base,
  sum(round(sol.qty * sol.rate, 2))               as order_value,
  case when so.expires_at < now() + interval '1 day'
       then true else false end                   as expiring_soon
from public.sales_order so
join public.party p        on p.id  = so.party_id
join public.route rt       on rt.id = p.route_id
left join public.app_user rep on rep.id = so.created_by
join public.sales_order_line sol on sol.order_id = so.id
where so.status in ('SUBMITTED', 'PARTIALLY_INVOICED')
group by so.id, p.code, p.name, rt.name, rep.full_name;

-- -----------------------------------------------------------------------------
-- Purchase register
-- -----------------------------------------------------------------------------

create or replace view public.v_purchase_register as
select
  pu.id        as purchase_id,
  pu.doc_no,
  pu.purchase_date,
  s.code       as supplier_code,
  s.name       as supplier_name,
  pu.supplier_bill_no,
  pu.supplier_bill_date,
  pu.gross_total,
  pu.other_charges,
  pu.net_total,
  pu.status,
  u.full_name  as created_by_name
from public.purchase pu
join public.supplier s on s.id = pu.supplier_id
left join public.app_user u on u.id = pu.created_by;

-- =============================================================================
-- Security and grants
--
-- security_invoker means each view runs with the caller's permissions, so RLS
-- on the underlying tables still applies. Without it, any of these would let a
-- rep read everything.
-- =============================================================================

do $$
declare v text;
begin
  foreach v in array array[
    'v_credit', 'v_invoice_outstanding', 'v_ageing', 'v_ageing_by_party',
    'v_ageing_by_route', 'v_unallocated_credit', 'v_party_balance',
    'v_party_ledger', 'v_sales_register', 'v_product_sales',
    'v_collection_report', 'v_collection_by_collector', 'v_pending_cheques',
    'v_stock_report', 'v_pending_orders', 'v_purchase_register'
  ] loop
    execute format('alter view public.%I set (security_invoker = true)', v);
    execute format('grant select on public.%I to authenticated', v);
  end loop;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>  016_import.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 016_import.sql
-- Bulk import of master data from a spreadsheet.
--
-- Design: validate everything first, then write, and write nothing at all if
-- any row is bad. A half-imported party list is worse than no import, because
-- nobody can tell which half is missing.
--
-- Every field arrives as TEXT and is checked before being cast. A cell reading
-- "12,500" then reports "not a number" against that row and column, instead of
-- the whole batch dying with "invalid input syntax for numeric".
--
-- Foreign keys are given as human-readable CODES, not ids — a spreadsheet says
-- route "R1", never a UUID.
--
-- Import order matters: routes and product groups first, since parties and
-- products point at them.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Small helpers used by every validator
-- -----------------------------------------------------------------------------

-- Trimmed, with blank treated as absent.
create or replace function app.imp_text(p text)
returns text
language sql
immutable
as $$ select nullif(btrim(coalesce(p, '')), ''); $$;

-- Is this text a number we can trust? Rejects "12,500", "1.2.3", "abc", "".
create or replace function app.imp_is_number(p text)
returns boolean
language sql
immutable
as $$ select btrim(coalesce(p, '')) ~ '^-?[0-9]+(\.[0-9]+)?$'; $$;

-- Accepts YYYY-MM-DD and DD/MM/YYYY, which is what spreadsheets in this part
-- of the world actually produce.
create or replace function app.imp_to_date(p text)
returns date
language plpgsql
immutable
as $$
declare t text := btrim(coalesce(p, ''));
begin
  if t = '' then return null; end if;
  if t ~ '^\d{4}-\d{2}-\d{2}$'        then return to_date(t, 'YYYY-MM-DD'); end if;
  if t ~ '^\d{1,2}/\d{1,2}/\d{4}$'    then return to_date(t, 'DD/MM/YYYY'); end if;
  if t ~ '^\d{1,2}-\d{1,2}-\d{4}$'    then return to_date(t, 'DD-MM-YYYY'); end if;
  return null;
exception when others then
  return null;
end;
$$;

create or replace function app.imp_is_date(p text)
returns boolean
language sql
immutable
as $$
  select btrim(coalesce(p, '')) = '' or app.imp_to_date(p) is not null;
$$;

-- One error, in the shape the client renders.
create or replace function app.imp_err(
  p_row integer, p_field text, p_value text, p_message text)
returns jsonb
language sql
immutable
as $$
  select jsonb_build_object(
    'row', p_row, 'field', p_field,
    'value', left(coalesce(p_value, ''), 80), 'message', p_message);
$$;

-- =============================================================================
-- The importer
--
--   select public.import_masters('party', '<rows>'::jsonb, true);   -- check
--   select public.import_masters('party', '<rows>'::jsonb, false);  -- import
--
-- Returns a report. On a real run with any error it raises SA004 and puts the
-- same report in the error DETAIL, so the transaction aborts and nothing is
-- written.
-- =============================================================================

create or replace function public.import_masters(
  p_entity  text,
  p_rows    jsonb,
  p_dry_run boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user     uuid := app.require_signed_in();
  v_errors   jsonb := '[]'::jsonb;
  v_count    integer := 0;
  v_imported integer := 0;
  v_report   jsonb;
begin
  if not app.is_admin() then
    raise exception 'Only Admin may import master data' using errcode = 'SA003';
  end if;

  if p_entity not in ('route', 'product_group', 'supplier', 'party', 'product') then
    raise exception 'Unknown entity "%". Expected route, product_group, supplier, party or product.',
      p_entity using errcode = 'SA004';
  end if;

  if jsonb_typeof(coalesce(p_rows, 'null'::jsonb)) <> 'array' then
    raise exception 'Rows must be a JSON array' using errcode = 'SA004';
  end if;

  if jsonb_array_length(p_rows) = 0 then
    raise exception 'There are no rows to import' using errcode = 'SA004';
  end if;

  -- Everything as text, with the spreadsheet row number carried through so an
  -- error can say "row 47" and mean the row the person is looking at.
  drop table if exists _imp;
  create temp table _imp on commit drop as
  select
    (ordinality + 1)::integer as row_no,   -- +1 because row 1 is the header
    e.value                   as r
  from jsonb_array_elements(p_rows) with ordinality as e(value, ordinality);

  v_count := (select count(*) from pg_temp._imp);

  -- ---------------------------------------------------------------------------
  -- Shared checks: every entity has a code and a name.
  -- ---------------------------------------------------------------------------
  select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
  from (
    select app.imp_err(row_no, 'code', r ->> 'code', 'Code is required') as err
      from pg_temp._imp where app.imp_text(r ->> 'code') is null
    union all
    select app.imp_err(row_no, 'name', r ->> 'name', 'Name is required')
      from pg_temp._imp where app.imp_text(r ->> 'name') is null
    union all
    -- Duplicated inside the sheet itself.
    select app.imp_err(row_no, 'code', r ->> 'code',
             'This code appears more than once in the sheet')
      from pg_temp._imp
     where app.imp_text(r ->> 'code') is not null
       and app.imp_text(r ->> 'code') in (
             select app.imp_text(d.r ->> 'code') from pg_temp._imp d
              group by 1 having count(*) > 1)
    union all
    -- The template ships with a sample row. Forgetting to delete it would
    -- otherwise create a party called "Example Store" that nobody notices
    -- until it turns up on a report.
    select app.imp_err(row_no, 'code', r ->> 'code',
             'This is the example row from the template — delete it before importing')
      from pg_temp._imp
     where upper(coalesce(app.imp_text(r ->> 'code'), '')) like 'EXAMPLE%'
  ) t;

  -- Already in the database. Import adds; it never silently overwrites.
  execute format($q$
    select coalesce(jsonb_agg(app.imp_err(i.row_no, 'code', i.r ->> 'code',
             'A %1$s with this code already exists')), '[]'::jsonb)
      from pg_temp._imp i
      join public.%1$I x on x.code = app.imp_text(i.r ->> 'code')
  $q$, p_entity)
  into v_report;
  v_errors := v_errors || v_report;

  -- ---------------------------------------------------------------------------
  -- Per-entity checks
  -- ---------------------------------------------------------------------------

  if p_entity = 'party' then
    select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
    from (
      select app.imp_err(row_no, 'route_code', r ->> 'route_code',
               'Route code is required') as err
        from pg_temp._imp where app.imp_text(r ->> 'route_code') is null
      union all
      select app.imp_err(row_no, 'route_code', r ->> 'route_code',
               'No route exists with this code — add it to the Routes sheet first')
        from pg_temp._imp i
       where app.imp_text(i.r ->> 'route_code') is not null
         and not exists (select 1 from public.route rt
                          where rt.code = app.imp_text(i.r ->> 'route_code'))
      union all
      select app.imp_err(row_no, 'credit_limit', r ->> 'credit_limit', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'credit_limit') is not null
         and not app.imp_is_number(r ->> 'credit_limit')
      union all
      select app.imp_err(row_no, 'credit_days', r ->> 'credit_days', 'Not a whole number')
        from pg_temp._imp
       where app.imp_text(r ->> 'credit_days') is not null
         and (not app.imp_is_number(r ->> 'credit_days')
              or (r ->> 'credit_days') ~ '\.')
      union all
      select app.imp_err(row_no, 'opening_balance', r ->> 'opening_balance', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'opening_balance') is not null
         and not app.imp_is_number(r ->> 'opening_balance')
      union all
      select app.imp_err(row_no, 'opening_balance_date', r ->> 'opening_balance_date',
               'Not a date — use YYYY-MM-DD or DD/MM/YYYY')
        from pg_temp._imp where not app.imp_is_date(r ->> 'opening_balance_date')
      union all
      -- An opening balance with no date cannot be aged.
      select app.imp_err(row_no, 'opening_balance_date', r ->> 'opening_balance_date',
               'An opening balance needs a date')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'opening_balance')
         and (r ->> 'opening_balance')::numeric <> 0
         and app.imp_text(r ->> 'opening_balance_date') is null
    ) t;
  end if;

  if p_entity = 'product' then
    select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
    from (
      select app.imp_err(row_no, 'group_code', r ->> 'group_code',
               'Group code is required') as err
        from pg_temp._imp where app.imp_text(r ->> 'group_code') is null
      union all
      select app.imp_err(row_no, 'group_code', r ->> 'group_code',
               'No product group exists with this code — add it to the Product Groups sheet first')
        from pg_temp._imp i
       where app.imp_text(i.r ->> 'group_code') is not null
         and not exists (select 1 from public.product_group g
                          where g.code = app.imp_text(i.r ->> 'group_code'))
      union all
      select app.imp_err(row_no, 'base_uom', r ->> 'base_uom',
               'Base unit is required, e.g. PCS or KG')
        from pg_temp._imp where app.imp_text(r ->> 'base_uom') is null
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'pack_size') is not null
         and not app.imp_is_number(r ->> 'pack_size')
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'Pack size must be above zero')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'pack_size')
         and (r ->> 'pack_size')::numeric <= 0
      union all
      -- A pack unit without a size, or a size without a unit, is a typo.
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'A pack unit needs a pack size above 1')
        from pg_temp._imp
       where app.imp_text(r ->> 'pack_uom') is not null
         and (app.imp_text(r ->> 'pack_size') is null
              or (app.imp_is_number(r ->> 'pack_size')
                  and (r ->> 'pack_size')::numeric <= 1))
      union all
      select app.imp_err(row_no, 'pack_uom', r ->> 'pack_uom',
               'A pack size above 1 needs a pack unit, e.g. BOX')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'pack_size')
         and (r ->> 'pack_size')::numeric > 1
         and app.imp_text(r ->> 'pack_uom') is null
      union all
      select app.imp_err(row_no, f.field, r ->> f.field, 'Not a number')
        from pg_temp._imp,
             (values ('sale_rate'), ('purchase_rate'), ('opening_qty'),
                     ('opening_rate')) as f(field)
       where app.imp_text(r ->> f.field) is not null
         and not app.imp_is_number(r ->> f.field)
      union all
      select app.imp_err(row_no, f.field, r ->> f.field, 'Cannot be negative')
        from pg_temp._imp,
             (values ('sale_rate'), ('purchase_rate'), ('opening_qty'),
                     ('opening_rate')) as f(field)
       where app.imp_is_number(r ->> f.field)
         and (r ->> f.field)::numeric < 0
      union all
      select app.imp_err(row_no, 'opening_date', r ->> 'opening_date',
               'Not a date — use YYYY-MM-DD or DD/MM/YYYY')
        from pg_temp._imp where not app.imp_is_date(r ->> 'opening_date')
      union all
      select app.imp_err(row_no, 'opening_date', r ->> 'opening_date',
               'Opening stock needs a date')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'opening_qty')
         and (r ->> 'opening_qty')::numeric > 0
         and app.imp_text(r ->> 'opening_date') is null
    ) t;
  end if;

  -- ---------------------------------------------------------------------------
  -- Report, and stop here if anything is wrong
  -- ---------------------------------------------------------------------------

  v_report := jsonb_build_object(
    'entity',       p_entity,
    'rows',         v_count,
    'errors',       jsonb_array_length(v_errors),
    'error_detail', (select jsonb_agg(e order by (e ->> 'row')::int, e ->> 'field')
                       from jsonb_array_elements(v_errors) e),
    'dry_run',      p_dry_run,
    'imported',     0);

  if jsonb_array_length(v_errors) > 0 then
    if p_dry_run then
      return v_report;                     -- checking: hand back the problems
    end if;
    raise exception 'Import refused: % row problem(s). Nothing was imported.',
      jsonb_array_length(v_errors)
      using errcode = 'SA004', detail = v_report::text;
  end if;

  if p_dry_run then
    return v_report || jsonb_build_object('would_import', v_count);
  end if;

  -- ---------------------------------------------------------------------------
  -- Write
  -- ---------------------------------------------------------------------------

  if p_entity = 'route' then
    insert into public.route (code, name)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name')
      from pg_temp._imp;

  elsif p_entity = 'product_group' then
    insert into public.product_group (code, name)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name')
      from pg_temp._imp;

  elsif p_entity = 'supplier' then
    insert into public.supplier (code, name, contact_person, phone, address, city)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name'),
           app.imp_text(r ->> 'contact_person'), app.imp_text(r ->> 'phone'),
           app.imp_text(r ->> 'address'), app.imp_text(r ->> 'city')
      from pg_temp._imp;

  elsif p_entity = 'party' then
    insert into public.party
      (code, name, route_id, contact_person, phone, whatsapp_phone,
       address, city, credit_limit, credit_days,
       opening_balance, opening_balance_date)
    select
      app.imp_text(i.r ->> 'code'),
      app.imp_text(i.r ->> 'name'),
      rt.id,
      app.imp_text(i.r ->> 'contact_person'),
      app.imp_text(i.r ->> 'phone'),
      coalesce(app.imp_text(i.r ->> 'whatsapp_phone'), app.imp_text(i.r ->> 'phone')),
      app.imp_text(i.r ->> 'address'),
      app.imp_text(i.r ->> 'city'),
      coalesce(nullif(i.r ->> 'credit_limit', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'credit_days', '')::smallint, 0),
      coalesce(nullif(i.r ->> 'opening_balance', '')::numeric, 0),
      app.imp_to_date(i.r ->> 'opening_balance_date')
    from pg_temp._imp i
    join public.route rt on rt.code = app.imp_text(i.r ->> 'route_code');

  elsif p_entity = 'product' then
    insert into public.product
      (code, name, group_id, base_uom, pack_uom, pack_size,
       sale_rate, purchase_rate, opening_qty, opening_rate, opening_date)
    select
      app.imp_text(i.r ->> 'code'),
      app.imp_text(i.r ->> 'name'),
      g.id,
      upper(app.imp_text(i.r ->> 'base_uom')),
      upper(app.imp_text(i.r ->> 'pack_uom')),
      coalesce(nullif(i.r ->> 'pack_size', '')::numeric, 1),
      coalesce(nullif(i.r ->> 'sale_rate', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'purchase_rate', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'opening_qty', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'opening_rate', '')::numeric, 0),
      app.imp_to_date(i.r ->> 'opening_date')
    from pg_temp._imp i
    join public.product_group g on g.code = app.imp_text(i.r ->> 'group_code');
  end if;

  get diagnostics v_imported = row_count;

  return v_report || jsonb_build_object('imported', v_imported);
end;
$$;

grant execute on function public.import_masters(text, jsonb, boolean) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  017_import_skip_existing.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 017_import_skip_existing.sql
-- Lets an import skip rows whose code is already in the database.
--
-- Why this exists: parties point at routes, so routes must be imported before
-- parties can even be checked. That means a workbook is loaded sheet by sheet,
-- and a failure on the Parties sheet leaves Routes already imported. Without a
-- skip, correcting the parties and re-uploading the same workbook would then
-- fail on Routes with "already exists" — and the person would be stuck.
--
-- Skipping is never silent. The report says how many rows were skipped and
-- lists their codes, so "import did nothing" always has a visible reason.
-- =============================================================================

-- The 3-argument version is replaced rather than overloaded: two functions of
-- the same name differing only by a defaulted argument makes every call
-- ambiguous.
drop function if exists public.import_masters(text, jsonb, boolean);

create or replace function public.import_masters(
  p_entity        text,
  p_rows          jsonb,
  p_dry_run       boolean default true,
  p_skip_existing boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user     uuid := app.require_signed_in();
  v_errors   jsonb := '[]'::jsonb;
  v_existing jsonb := '[]'::jsonb;
  v_count    integer := 0;
  v_skipped  integer := 0;
  v_imported integer := 0;
  v_report   jsonb;
  v_tmp      jsonb;
begin
  if not app.is_admin() then
    raise exception 'Only Admin may import master data' using errcode = 'SA003';
  end if;

  if p_entity not in ('route', 'product_group', 'supplier', 'party', 'product') then
    raise exception 'Unknown entity "%". Expected route, product_group, supplier, party or product.',
      p_entity using errcode = 'SA004';
  end if;

  if jsonb_typeof(coalesce(p_rows, 'null'::jsonb)) <> 'array' then
    raise exception 'Rows must be a JSON array' using errcode = 'SA004';
  end if;

  if jsonb_array_length(p_rows) = 0 then
    raise exception 'There are no rows to import' using errcode = 'SA004';
  end if;

  drop table if exists _imp;
  create temp table _imp on commit drop as
  select
    (ordinality + 1)::integer as row_no,   -- +1 because row 1 is the header
    e.value                   as r
  from jsonb_array_elements(p_rows) with ordinality as e(value, ordinality);

  v_count := (select count(*) from pg_temp._imp);

  -- ---------------------------------------------------------------------------
  -- Which rows are already in the database
  -- ---------------------------------------------------------------------------
  execute format($q$
    select coalesce(jsonb_agg(jsonb_build_object(
             'row', i.row_no, 'code', app.imp_text(i.r ->> 'code'))), '[]'::jsonb)
      from pg_temp._imp i
      join public.%1$I x on x.code = app.imp_text(i.r ->> 'code')
  $q$, p_entity)
  into v_existing;

  v_skipped := jsonb_array_length(v_existing);

  -- When skipping, take them out before anything else is checked: a row that
  -- is not being imported should not produce errors about its other columns.
  if p_skip_existing and v_skipped > 0 then
    delete from pg_temp._imp i
     where i.row_no in (
       select (e ->> 'row')::int from jsonb_array_elements(v_existing) e);

    if not exists (select 1 from pg_temp._imp) then
      return jsonb_build_object(
        'entity', p_entity, 'rows', v_count, 'errors', 0,
        'error_detail', '[]'::jsonb, 'dry_run', p_dry_run,
        'imported', 0, 'skipped', v_skipped, 'skipped_detail', v_existing,
        'note', 'Every row was already in the database. Nothing to import.');
    end if;
  end if;

  -- ---------------------------------------------------------------------------
  -- Shared checks
  -- ---------------------------------------------------------------------------
  select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
  from (
    select app.imp_err(row_no, 'code', r ->> 'code', 'Code is required') as err
      from pg_temp._imp where app.imp_text(r ->> 'code') is null
    union all
    select app.imp_err(row_no, 'name', r ->> 'name', 'Name is required')
      from pg_temp._imp where app.imp_text(r ->> 'name') is null
    union all
    select app.imp_err(row_no, 'code', r ->> 'code',
             'This code appears more than once in the sheet')
      from pg_temp._imp
     where app.imp_text(r ->> 'code') is not null
       and app.imp_text(r ->> 'code') in (
             select app.imp_text(d.r ->> 'code') from pg_temp._imp d
              group by 1 having count(*) > 1)
    union all
    select app.imp_err(row_no, 'code', r ->> 'code',
             'This is the example row from the template — delete it before importing')
      from pg_temp._imp
     where upper(coalesce(app.imp_text(r ->> 'code'), '')) like 'EXAMPLE%'
  ) t;

  -- Already in the database, and not skipping.
  if not p_skip_existing then
    select coalesce(jsonb_agg(app.imp_err(
             (e ->> 'row')::int, 'code', e ->> 'code',
             format('A %s with this code already exists', p_entity))), '[]'::jsonb)
      into v_tmp
      from jsonb_array_elements(v_existing) e;
    v_errors := v_errors || v_tmp;
  end if;

  -- ---------------------------------------------------------------------------
  -- Per-entity checks
  -- ---------------------------------------------------------------------------

  if p_entity = 'party' then
    select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
    from (
      select app.imp_err(row_no, 'route_code', r ->> 'route_code',
               'Route code is required') as err
        from pg_temp._imp where app.imp_text(r ->> 'route_code') is null
      union all
      select app.imp_err(row_no, 'route_code', r ->> 'route_code',
               'No route exists with this code — import the Routes sheet first')
        from pg_temp._imp i
       where app.imp_text(i.r ->> 'route_code') is not null
         and not exists (select 1 from public.route rt
                          where rt.code = app.imp_text(i.r ->> 'route_code'))
      union all
      select app.imp_err(row_no, 'credit_limit', r ->> 'credit_limit', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'credit_limit') is not null
         and not app.imp_is_number(r ->> 'credit_limit')
      union all
      select app.imp_err(row_no, 'credit_days', r ->> 'credit_days', 'Not a whole number')
        from pg_temp._imp
       where app.imp_text(r ->> 'credit_days') is not null
         and (not app.imp_is_number(r ->> 'credit_days')
              or (r ->> 'credit_days') ~ '\.')
      union all
      select app.imp_err(row_no, 'opening_balance', r ->> 'opening_balance', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'opening_balance') is not null
         and not app.imp_is_number(r ->> 'opening_balance')
      union all
      select app.imp_err(row_no, 'opening_balance_date', r ->> 'opening_balance_date',
               'Not a date — use YYYY-MM-DD or DD/MM/YYYY')
        from pg_temp._imp where not app.imp_is_date(r ->> 'opening_balance_date')
      union all
      select app.imp_err(row_no, 'opening_balance_date', r ->> 'opening_balance_date',
               'An opening balance needs a date')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'opening_balance')
         and (r ->> 'opening_balance')::numeric <> 0
         and app.imp_text(r ->> 'opening_balance_date') is null
    ) t;
  end if;

  if p_entity = 'product' then
    select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
    from (
      select app.imp_err(row_no, 'group_code', r ->> 'group_code',
               'Group code is required') as err
        from pg_temp._imp where app.imp_text(r ->> 'group_code') is null
      union all
      select app.imp_err(row_no, 'group_code', r ->> 'group_code',
               'No product group exists with this code — import the Product Groups sheet first')
        from pg_temp._imp i
       where app.imp_text(i.r ->> 'group_code') is not null
         and not exists (select 1 from public.product_group g
                          where g.code = app.imp_text(i.r ->> 'group_code'))
      union all
      select app.imp_err(row_no, 'base_uom', r ->> 'base_uom',
               'Base unit is required, e.g. PCS or KG')
        from pg_temp._imp where app.imp_text(r ->> 'base_uom') is null
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'pack_size') is not null
         and not app.imp_is_number(r ->> 'pack_size')
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'Pack size must be above zero')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'pack_size')
         and (r ->> 'pack_size')::numeric <= 0
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'A pack unit needs a pack size above 1')
        from pg_temp._imp
       where app.imp_text(r ->> 'pack_uom') is not null
         and (app.imp_text(r ->> 'pack_size') is null
              or (app.imp_is_number(r ->> 'pack_size')
                  and (r ->> 'pack_size')::numeric <= 1))
      union all
      select app.imp_err(row_no, 'pack_uom', r ->> 'pack_uom',
               'A pack size above 1 needs a pack unit, e.g. BOX')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'pack_size')
         and (r ->> 'pack_size')::numeric > 1
         and app.imp_text(r ->> 'pack_uom') is null
      union all
      select app.imp_err(row_no, f.field, r ->> f.field, 'Not a number')
        from pg_temp._imp,
             (values ('sale_rate'), ('purchase_rate'), ('opening_qty'),
                     ('opening_rate')) as f(field)
       where app.imp_text(r ->> f.field) is not null
         and not app.imp_is_number(r ->> f.field)
      union all
      select app.imp_err(row_no, f.field, r ->> f.field, 'Cannot be negative')
        from pg_temp._imp,
             (values ('sale_rate'), ('purchase_rate'), ('opening_qty'),
                     ('opening_rate')) as f(field)
       where app.imp_is_number(r ->> f.field)
         and (r ->> f.field)::numeric < 0
      union all
      select app.imp_err(row_no, 'opening_date', r ->> 'opening_date',
               'Not a date — use YYYY-MM-DD or DD/MM/YYYY')
        from pg_temp._imp where not app.imp_is_date(r ->> 'opening_date')
      union all
      select app.imp_err(row_no, 'opening_date', r ->> 'opening_date',
               'Opening stock needs a date')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'opening_qty')
         and (r ->> 'opening_qty')::numeric > 0
         and app.imp_text(r ->> 'opening_date') is null
    ) t;
  end if;

  -- ---------------------------------------------------------------------------
  -- Report
  -- ---------------------------------------------------------------------------

  v_report := jsonb_build_object(
    'entity',         p_entity,
    'rows',           v_count,
    'errors',         jsonb_array_length(v_errors),
    'error_detail',   coalesce((select jsonb_agg(e order by (e ->> 'row')::int, e ->> 'field')
                                  from jsonb_array_elements(v_errors) e), '[]'::jsonb),
    'dry_run',        p_dry_run,
    'imported',       0,
    'skipped',        case when p_skip_existing then v_skipped else 0 end,
    'skipped_detail', case when p_skip_existing then v_existing else '[]'::jsonb end,
    'already_exists', v_skipped);

  if jsonb_array_length(v_errors) > 0 then
    if p_dry_run then
      return v_report;
    end if;
    raise exception 'Import refused: % row problem(s). Nothing was imported.',
      jsonb_array_length(v_errors)
      using errcode = 'SA004', detail = v_report::text;
  end if;

  if p_dry_run then
    return v_report || jsonb_build_object(
      'would_import', (select count(*) from pg_temp._imp));
  end if;

  -- ---------------------------------------------------------------------------
  -- Write
  -- ---------------------------------------------------------------------------

  if p_entity = 'route' then
    insert into public.route (code, name)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name')
      from pg_temp._imp;

  elsif p_entity = 'product_group' then
    insert into public.product_group (code, name)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name')
      from pg_temp._imp;

  elsif p_entity = 'supplier' then
    insert into public.supplier (code, name, contact_person, phone, address, city)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name'),
           app.imp_text(r ->> 'contact_person'), app.imp_text(r ->> 'phone'),
           app.imp_text(r ->> 'address'), app.imp_text(r ->> 'city')
      from pg_temp._imp;

  elsif p_entity = 'party' then
    insert into public.party
      (code, name, route_id, contact_person, phone, whatsapp_phone,
       address, city, credit_limit, credit_days,
       opening_balance, opening_balance_date)
    select
      app.imp_text(i.r ->> 'code'),
      app.imp_text(i.r ->> 'name'),
      rt.id,
      app.imp_text(i.r ->> 'contact_person'),
      app.imp_text(i.r ->> 'phone'),
      coalesce(app.imp_text(i.r ->> 'whatsapp_phone'), app.imp_text(i.r ->> 'phone')),
      app.imp_text(i.r ->> 'address'),
      app.imp_text(i.r ->> 'city'),
      coalesce(nullif(i.r ->> 'credit_limit', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'credit_days', '')::smallint, 0),
      coalesce(nullif(i.r ->> 'opening_balance', '')::numeric, 0),
      app.imp_to_date(i.r ->> 'opening_balance_date')
    from pg_temp._imp i
    join public.route rt on rt.code = app.imp_text(i.r ->> 'route_code');

  elsif p_entity = 'product' then
    insert into public.product
      (code, name, group_id, base_uom, pack_uom, pack_size,
       sale_rate, purchase_rate, opening_qty, opening_rate, opening_date)
    select
      app.imp_text(i.r ->> 'code'),
      app.imp_text(i.r ->> 'name'),
      g.id,
      upper(app.imp_text(i.r ->> 'base_uom')),
      upper(app.imp_text(i.r ->> 'pack_uom')),
      coalesce(nullif(i.r ->> 'pack_size', '')::numeric, 1),
      coalesce(nullif(i.r ->> 'sale_rate', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'purchase_rate', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'opening_qty', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'opening_rate', '')::numeric, 0),
      app.imp_to_date(i.r ->> 'opening_date')
    from pg_temp._imp i
    join public.product_group g on g.code = app.imp_text(i.r ->> 'group_code');
  end if;

  get diagnostics v_imported = row_count;

  return v_report || jsonb_build_object('imported', v_imported);
end;
$$;

grant execute on function public.import_masters(text, jsonb, boolean, boolean)
  to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  018_pack_prices.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 018_pack_prices.sql
-- Prices can be entered per pack. The per-unit rate is worked out from it.
--
-- People price by the box: "a box of 24 is 500". Typing 20.8333 per piece is
-- slower and error-prone, and it also loses money. 20.8333 x 24 is 499.9992,
-- so a bill for 100 boxes would come to 49,999.92 instead of 50,000.00.
--
-- The fix is to keep the pack price as it was typed:
--
--   pack_sale_rate      500      (what was entered, used when billing by BOX)
--   sale_rate           20.8333  (derived, used when billing loose by PCS)
--
-- A trigger keeps the two in step. Whenever a pack price is set, the per-unit
-- rate is recalculated from it. That includes a later change of pack size.
-- If someone later edits the per-unit rate on its own, the pack price no longer
-- applies and is cleared. After that, the pack rate falls back to rate x size,
-- so the two can never quietly disagree.
--
-- The Products sheet gains sale_price, purchase_price and opening_price. Each
-- one is a price per PACK when the row has a pack unit, and per base unit
-- otherwise. The older sale_rate / purchase_rate / opening_rate columns still
-- work exactly as before (always per base unit), so an old workbook imports
-- unchanged. A row that fills in both styles for the same price is refused
-- rather than guessed at.
--
-- Run this file once in the Supabase SQL Editor. Safe to run more than once.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Columns
-- -----------------------------------------------------------------------------

alter table public.product
  add column if not exists pack_sale_rate     numeric(14,4),
  add column if not exists pack_purchase_rate numeric(14,4);

alter table public.product drop constraint if exists product_pack_rates_valid;
alter table public.product add constraint product_pack_rates_valid
  check (
    coalesce(pack_sale_rate, 0) >= 0
    and coalesce(pack_purchase_rate, 0) >= 0
    and (pack_uom is not null or (pack_sale_rate is null and pack_purchase_rate is null))
  ) not valid;
alter table public.product validate constraint product_pack_rates_valid;

comment on column public.product.pack_sale_rate is
  'Selling price of one pack, as entered. When set, sale_rate is derived from it.';
comment on column public.product.pack_purchase_rate is
  'Cost of one pack, as entered. When set, purchase_rate is derived from it.';
comment on column public.product.sale_rate is
  'Selling price per BASE unit. Derived from pack_sale_rate when that is set.';

-- -----------------------------------------------------------------------------
-- Keep pack and unit rates in step
-- -----------------------------------------------------------------------------

create or replace function app.product_derive_rates()
returns trigger
language plpgsql
as $$
begin
  -- A product with no pack cannot have a pack price.
  if new.pack_uom is null then
    new.pack_sale_rate     := null;
    new.pack_purchase_rate := null;
  end if;

  -- A per-unit rate edited on its own replaces the pack price. It does not get
  -- overwritten by it.
  if tg_op = 'UPDATE' then
    if new.sale_rate is distinct from old.sale_rate
       and new.pack_sale_rate is not distinct from old.pack_sale_rate then
      new.pack_sale_rate := null;
    end if;
    if new.purchase_rate is distinct from old.purchase_rate
       and new.pack_purchase_rate is not distinct from old.pack_purchase_rate then
      new.pack_purchase_rate := null;
    end if;
  end if;

  if new.pack_sale_rate is not null then
    new.sale_rate := round(new.pack_sale_rate / new.pack_size, 4);
  end if;
  if new.pack_purchase_rate is not null then
    new.purchase_rate := round(new.pack_purchase_rate / new.pack_size, 4);
  end if;

  return new;
end;
$$;

drop trigger if exists product_derive_rates on public.product;
create trigger product_derive_rates
  before insert or update on public.product
  for each row execute function app.product_derive_rates();

-- -----------------------------------------------------------------------------
-- Stock report carries the pack price, so screens need not recompute it.
-- New columns go on the end: CREATE OR REPLACE VIEW can only append.
-- -----------------------------------------------------------------------------

create or replace view public.v_stock_report as
select
  pr.id        as product_id,
  pr.code      as product_code,
  pr.name      as product_name,
  pg.name      as group_name,
  pr.base_uom,
  pr.pack_uom,
  pr.pack_size,
  ps.on_hand,
  ps.reserved,
  ps.available,
  case when pr.pack_size > 1
       then floor(ps.available / pr.pack_size) else null end as available_packs,
  pr.sale_rate,
  pr.purchase_rate,
  ps.on_hand * pr.purchase_rate as stock_value_at_cost,
  ps.updated_at,
  pr.is_active,
  -- The price of one pack: as entered if it was, otherwise rate x size.
  case when pr.pack_uom is not null
       then coalesce(pr.pack_sale_rate, round(pr.sale_rate * pr.pack_size, 2))
  end as pack_sale_rate,
  case when pr.pack_uom is not null
       then coalesce(pr.pack_purchase_rate, round(pr.purchase_rate * pr.pack_size, 2))
  end as pack_purchase_rate
from public.product pr
join public.product_group pg on pg.id = pr.group_id
join public.product_stock ps on ps.product_id = pr.id;

-- Replacing a view can reset its options. Reps must still only see what RLS
-- allows, so set this again explicitly.
alter view public.v_stock_report set (security_invoker = true);
grant select on public.v_stock_report to authenticated;

-- -----------------------------------------------------------------------------
-- Import: same function and signature as 017, with the product sheet
-- understanding the new price columns.
-- -----------------------------------------------------------------------------

create or replace function public.import_masters(
  p_entity        text,
  p_rows          jsonb,
  p_dry_run       boolean default true,
  p_skip_existing boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user     uuid := app.require_signed_in();
  v_errors   jsonb := '[]'::jsonb;
  v_existing jsonb := '[]'::jsonb;
  v_count    integer := 0;
  v_skipped  integer := 0;
  v_imported integer := 0;
  v_report   jsonb;
  v_tmp      jsonb;
begin
  if not app.is_admin() then
    raise exception 'Only Admin may import master data' using errcode = 'SA003';
  end if;

  if p_entity not in ('route', 'product_group', 'supplier', 'party', 'product') then
    raise exception 'Unknown entity "%". Expected route, product_group, supplier, party or product.',
      p_entity using errcode = 'SA004';
  end if;

  if jsonb_typeof(coalesce(p_rows, 'null'::jsonb)) <> 'array' then
    raise exception 'Rows must be a JSON array' using errcode = 'SA004';
  end if;

  if jsonb_array_length(p_rows) = 0 then
    raise exception 'There are no rows to import' using errcode = 'SA004';
  end if;

  drop table if exists _imp;
  create temp table _imp on commit drop as
  select
    (ordinality + 1)::integer as row_no,   -- +1 because row 1 is the header
    e.value                   as r
  from jsonb_array_elements(p_rows) with ordinality as e(value, ordinality);

  v_count := (select count(*) from pg_temp._imp);

  -- ---------------------------------------------------------------------------
  -- Which rows are already in the database
  -- ---------------------------------------------------------------------------
  execute format($q$
    select coalesce(jsonb_agg(jsonb_build_object(
             'row', i.row_no, 'code', app.imp_text(i.r ->> 'code'))), '[]'::jsonb)
      from pg_temp._imp i
      join public.%1$I x on x.code = app.imp_text(i.r ->> 'code')
  $q$, p_entity)
  into v_existing;

  v_skipped := jsonb_array_length(v_existing);

  -- When skipping, take them out before anything else is checked: a row that
  -- is not being imported should not produce errors about its other columns.
  if p_skip_existing and v_skipped > 0 then
    delete from pg_temp._imp i
     where i.row_no in (
       select (e ->> 'row')::int from jsonb_array_elements(v_existing) e);

    if not exists (select 1 from pg_temp._imp) then
      return jsonb_build_object(
        'entity', p_entity, 'rows', v_count, 'errors', 0,
        'error_detail', '[]'::jsonb, 'dry_run', p_dry_run,
        'imported', 0, 'skipped', v_skipped, 'skipped_detail', v_existing,
        'note', 'Every row was already in the database. Nothing to import.');
    end if;
  end if;

  -- ---------------------------------------------------------------------------
  -- Shared checks
  -- ---------------------------------------------------------------------------
  select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
  from (
    select app.imp_err(row_no, 'code', r ->> 'code', 'Code is required') as err
      from pg_temp._imp where app.imp_text(r ->> 'code') is null
    union all
    select app.imp_err(row_no, 'name', r ->> 'name', 'Name is required')
      from pg_temp._imp where app.imp_text(r ->> 'name') is null
    union all
    select app.imp_err(row_no, 'code', r ->> 'code',
             'This code appears more than once in the sheet')
      from pg_temp._imp
     where app.imp_text(r ->> 'code') is not null
       and app.imp_text(r ->> 'code') in (
             select app.imp_text(d.r ->> 'code') from pg_temp._imp d
              group by 1 having count(*) > 1)
    union all
    select app.imp_err(row_no, 'code', r ->> 'code',
             'This is the example row from the template — delete it before importing')
      from pg_temp._imp
     where upper(coalesce(app.imp_text(r ->> 'code'), '')) like 'EXAMPLE%'
  ) t;

  -- Already in the database, and not skipping.
  if not p_skip_existing then
    select coalesce(jsonb_agg(app.imp_err(
             (e ->> 'row')::int, 'code', e ->> 'code',
             format('A %s with this code already exists', p_entity))), '[]'::jsonb)
      into v_tmp
      from jsonb_array_elements(v_existing) e;
    v_errors := v_errors || v_tmp;
  end if;

  -- ---------------------------------------------------------------------------
  -- Per-entity checks
  -- ---------------------------------------------------------------------------

  if p_entity = 'party' then
    select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
    from (
      select app.imp_err(row_no, 'route_code', r ->> 'route_code',
               'Route code is required') as err
        from pg_temp._imp where app.imp_text(r ->> 'route_code') is null
      union all
      select app.imp_err(row_no, 'route_code', r ->> 'route_code',
               'No route exists with this code — import the Routes sheet first')
        from pg_temp._imp i
       where app.imp_text(i.r ->> 'route_code') is not null
         and not exists (select 1 from public.route rt
                          where rt.code = app.imp_text(i.r ->> 'route_code'))
      union all
      select app.imp_err(row_no, 'credit_limit', r ->> 'credit_limit', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'credit_limit') is not null
         and not app.imp_is_number(r ->> 'credit_limit')
      union all
      select app.imp_err(row_no, 'credit_days', r ->> 'credit_days', 'Not a whole number')
        from pg_temp._imp
       where app.imp_text(r ->> 'credit_days') is not null
         and (not app.imp_is_number(r ->> 'credit_days')
              or (r ->> 'credit_days') ~ '\.')
      union all
      select app.imp_err(row_no, 'opening_balance', r ->> 'opening_balance', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'opening_balance') is not null
         and not app.imp_is_number(r ->> 'opening_balance')
      union all
      select app.imp_err(row_no, 'opening_balance_date', r ->> 'opening_balance_date',
               'Not a date — use YYYY-MM-DD or DD/MM/YYYY')
        from pg_temp._imp where not app.imp_is_date(r ->> 'opening_balance_date')
      union all
      select app.imp_err(row_no, 'opening_balance_date', r ->> 'opening_balance_date',
               'An opening balance needs a date')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'opening_balance')
         and (r ->> 'opening_balance')::numeric <> 0
         and app.imp_text(r ->> 'opening_balance_date') is null
    ) t;
  end if;

  if p_entity = 'product' then
    select v_errors || coalesce(jsonb_agg(err), '[]'::jsonb) into v_errors
    from (
      select app.imp_err(row_no, 'group_code', r ->> 'group_code',
               'Group code is required') as err
        from pg_temp._imp where app.imp_text(r ->> 'group_code') is null
      union all
      select app.imp_err(row_no, 'group_code', r ->> 'group_code',
               'No product group exists with this code — import the Product Groups sheet first')
        from pg_temp._imp i
       where app.imp_text(i.r ->> 'group_code') is not null
         and not exists (select 1 from public.product_group g
                          where g.code = app.imp_text(i.r ->> 'group_code'))
      union all
      select app.imp_err(row_no, 'base_uom', r ->> 'base_uom',
               'Base unit is required, e.g. PCS or KG')
        from pg_temp._imp where app.imp_text(r ->> 'base_uom') is null
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size', 'Not a number')
        from pg_temp._imp
       where app.imp_text(r ->> 'pack_size') is not null
         and not app.imp_is_number(r ->> 'pack_size')
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'Pack size must be above zero')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'pack_size')
         and (r ->> 'pack_size')::numeric <= 0
      union all
      select app.imp_err(row_no, 'pack_size', r ->> 'pack_size',
               'A pack unit needs a pack size above 1')
        from pg_temp._imp
       where app.imp_text(r ->> 'pack_uom') is not null
         and (app.imp_text(r ->> 'pack_size') is null
              or (app.imp_is_number(r ->> 'pack_size')
                  and (r ->> 'pack_size')::numeric <= 1))
      union all
      select app.imp_err(row_no, 'pack_uom', r ->> 'pack_uom',
               'A pack size above 1 needs a pack unit, e.g. BOX')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'pack_size')
         and (r ->> 'pack_size')::numeric > 1
         and app.imp_text(r ->> 'pack_uom') is null
      union all
      select app.imp_err(row_no, f.field, r ->> f.field, 'Not a number')
        from pg_temp._imp,
             (values ('sale_rate'), ('purchase_rate'), ('opening_qty'),
                     ('opening_rate'), ('sale_price'), ('purchase_price'),
                     ('opening_price')) as f(field)
       where app.imp_text(r ->> f.field) is not null
         and not app.imp_is_number(r ->> f.field)
      union all
      select app.imp_err(row_no, f.field, r ->> f.field, 'Cannot be negative')
        from pg_temp._imp,
             (values ('sale_rate'), ('purchase_rate'), ('opening_qty'),
                     ('opening_rate'), ('sale_price'), ('purchase_price'),
                     ('opening_price')) as f(field)
       where app.imp_is_number(r ->> f.field)
         and (r ->> f.field)::numeric < 0
      union all
      -- Two prices for the same thing, in two different units, would be a
      -- guess either way. Ask instead.
      select app.imp_err(row_no, f.new_field, r ->> f.new_field,
               'Fill in ' || f.new_field || ' or ' || f.old_field || ', not both. '
               || f.new_field || ' is per pack when there is a pack unit; '
               || f.old_field || ' is always per base unit.')
        from pg_temp._imp,
             (values ('sale_price', 'sale_rate'),
                     ('purchase_price', 'purchase_rate'),
                     ('opening_price', 'opening_rate')) as f(new_field, old_field)
       where app.imp_text(r ->> f.new_field) is not null
         and app.imp_text(r ->> f.old_field) is not null
      union all
      select app.imp_err(row_no, 'opening_date', r ->> 'opening_date',
               'Not a date — use YYYY-MM-DD or DD/MM/YYYY')
        from pg_temp._imp where not app.imp_is_date(r ->> 'opening_date')
      union all
      select app.imp_err(row_no, 'opening_date', r ->> 'opening_date',
               'Opening stock needs a date')
        from pg_temp._imp
       where app.imp_is_number(r ->> 'opening_qty')
         and (r ->> 'opening_qty')::numeric > 0
         and app.imp_text(r ->> 'opening_date') is null
    ) t;
  end if;

  -- ---------------------------------------------------------------------------
  -- Report
  -- ---------------------------------------------------------------------------

  v_report := jsonb_build_object(
    'entity',         p_entity,
    'rows',           v_count,
    'errors',         jsonb_array_length(v_errors),
    'error_detail',   coalesce((select jsonb_agg(e order by (e ->> 'row')::int, e ->> 'field')
                                  from jsonb_array_elements(v_errors) e), '[]'::jsonb),
    'dry_run',        p_dry_run,
    'imported',       0,
    'skipped',        case when p_skip_existing then v_skipped else 0 end,
    'skipped_detail', case when p_skip_existing then v_existing else '[]'::jsonb end,
    'already_exists', v_skipped);

  if jsonb_array_length(v_errors) > 0 then
    if p_dry_run then
      return v_report;
    end if;
    raise exception 'Import refused: % row problem(s). Nothing was imported.',
      jsonb_array_length(v_errors)
      using errcode = 'SA004', detail = v_report::text;
  end if;

  if p_dry_run then
    return v_report || jsonb_build_object(
      'would_import', (select count(*) from pg_temp._imp));
  end if;

  -- ---------------------------------------------------------------------------
  -- Write
  -- ---------------------------------------------------------------------------

  if p_entity = 'route' then
    insert into public.route (code, name)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name')
      from pg_temp._imp;

  elsif p_entity = 'product_group' then
    insert into public.product_group (code, name)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name')
      from pg_temp._imp;

  elsif p_entity = 'supplier' then
    insert into public.supplier (code, name, contact_person, phone, address, city)
    select app.imp_text(r ->> 'code'), app.imp_text(r ->> 'name'),
           app.imp_text(r ->> 'contact_person'), app.imp_text(r ->> 'phone'),
           app.imp_text(r ->> 'address'), app.imp_text(r ->> 'city')
      from pg_temp._imp;

  elsif p_entity = 'party' then
    insert into public.party
      (code, name, route_id, contact_person, phone, whatsapp_phone,
       address, city, credit_limit, credit_days,
       opening_balance, opening_balance_date)
    select
      app.imp_text(i.r ->> 'code'),
      app.imp_text(i.r ->> 'name'),
      rt.id,
      app.imp_text(i.r ->> 'contact_person'),
      app.imp_text(i.r ->> 'phone'),
      coalesce(app.imp_text(i.r ->> 'whatsapp_phone'), app.imp_text(i.r ->> 'phone')),
      app.imp_text(i.r ->> 'address'),
      app.imp_text(i.r ->> 'city'),
      coalesce(nullif(i.r ->> 'credit_limit', '')::numeric, 0),
      coalesce(nullif(i.r ->> 'credit_days', '')::smallint, 0),
      coalesce(nullif(i.r ->> 'opening_balance', '')::numeric, 0),
      app.imp_to_date(i.r ->> 'opening_balance_date')
    from pg_temp._imp i
    join public.route rt on rt.code = app.imp_text(i.r ->> 'route_code');

  elsif p_entity = 'product' then
    -- A *_price column is per pack when the row has a pack unit, and per base
    -- unit otherwise. A *_rate column is always per base unit. Validation has
    -- already made sure at most one of each pair is filled in.
    --
    -- The pack price is stored as typed; the trigger derives the unit rate.
    insert into public.product
      (code, name, group_id, base_uom, pack_uom, pack_size,
       sale_rate, purchase_rate, pack_sale_rate, pack_purchase_rate,
       opening_qty, opening_rate, opening_date)
    select
      x.code, x.name, x.group_id, x.base_uom, x.pack_uom, x.pack_size,
      coalesce(case when x.pack_uom is null then x.sale_price end, x.sale_rate, 0),
      coalesce(case when x.pack_uom is null then x.purchase_price end, x.purchase_rate, 0),
      case when x.pack_uom is not null then x.sale_price end,
      case when x.pack_uom is not null then x.purchase_price end,
      x.opening_qty,
      coalesce(case when x.pack_uom is null then x.opening_price
                    else round(x.opening_price / x.pack_size, 4) end,
               x.opening_rate, 0),
      x.opening_date
    from (
      select
        app.imp_text(i.r ->> 'code')                              as code,
        app.imp_text(i.r ->> 'name')                              as name,
        g.id                                                      as group_id,
        upper(app.imp_text(i.r ->> 'base_uom'))                   as base_uom,
        upper(app.imp_text(i.r ->> 'pack_uom'))                   as pack_uom,
        coalesce(app.imp_text(i.r ->> 'pack_size')::numeric, 1)   as pack_size,
        app.imp_text(i.r ->> 'sale_price')::numeric               as sale_price,
        app.imp_text(i.r ->> 'purchase_price')::numeric           as purchase_price,
        app.imp_text(i.r ->> 'opening_price')::numeric            as opening_price,
        app.imp_text(i.r ->> 'sale_rate')::numeric                as sale_rate,
        app.imp_text(i.r ->> 'purchase_rate')::numeric            as purchase_rate,
        app.imp_text(i.r ->> 'opening_rate')::numeric             as opening_rate,
        coalesce(app.imp_text(i.r ->> 'opening_qty')::numeric, 0) as opening_qty,
        app.imp_to_date(i.r ->> 'opening_date')                   as opening_date
      from pg_temp._imp i
      join public.product_group g on g.code = app.imp_text(i.r ->> 'group_code')
    ) x;
  end if;

  get diagnostics v_imported = row_count;

  return v_report || jsonb_build_object('imported', v_imported);
end;
$$;

grant execute on function public.import_masters(text, jsonb, boolean, boolean)
  to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  019_master_editing.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 019_master_editing.sql
-- Rules for editing parties and products by hand, now that the app has
-- screens for it.
--
-- Admin could always update these tables directly. RLS allowed it. What was
-- missing were the rules about WHICH fields may change, and when:
--
--   * Codes never change. Spreadsheets, imports and people refer to things by
--     code. Renaming one quietly breaks every list that uses the old code.
--
--   * A party's opening balance is frozen once the party has any document:
--     an order, invoice, return or receipt. After that, ageing and the party
--     ledger are built on top of it, and changing it would rewrite history.
--
--   * A product's opening stock is frozen once it has been posted to the stock
--     ledger. The ledger is append-only, so editing opening_qty afterwards
--     would change nothing except make the product record lie about it.
--
-- These rules live in the database, not the screens, so a change from any
-- route (app, SQL Editor, a future bulk update) meets the same rules.
--
-- Run this file once in the Supabase SQL Editor. Safe to run more than once.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Questions the screens need to ask. SECURITY DEFINER so the answer is the
-- same whoever asks, even if they cannot read the documents themselves. They
-- return only yes/no, never the documents.
-- -----------------------------------------------------------------------------

create or replace function public.party_has_documents(p_party_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_catalog
as $$
  select exists (select 1 from public.sales_order   where party_id = p_party_id)
      or exists (select 1 from public.sales_invoice where party_id = p_party_id)
      or exists (select 1 from public.sales_return  where party_id = p_party_id)
      or exists (select 1 from public.receipt       where party_id = p_party_id);
$$;

create or replace function public.product_opening_posted(p_product_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_catalog
as $$
  select exists (select 1 from public.stock_ledger
                  where product_id = p_product_id and doc_type = 'OPENING');
$$;

revoke all on function public.party_has_documents(uuid)    from public, anon;
revoke all on function public.product_opening_posted(uuid) from public, anon;
grant execute on function public.party_has_documents(uuid)    to authenticated;
grant execute on function public.product_opening_posted(uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- Guards
-- -----------------------------------------------------------------------------

create or replace function app.party_guard()
returns trigger
language plpgsql
as $$
begin
  if new.code is distinct from old.code then
    raise exception 'A party code cannot be changed (% stays %).', old.name, old.code
      using errcode = 'SA004';
  end if;

  if (new.opening_balance is distinct from old.opening_balance
      or new.opening_balance_date is distinct from old.opening_balance_date)
     and public.party_has_documents(old.id) then
    raise exception 'The opening balance of % is fixed: the party already has orders, bills or payments.',
      old.name using errcode = 'SA002';
  end if;

  return new;
end;
$$;

drop trigger if exists party_guard on public.party;
create trigger party_guard
  before update on public.party
  for each row execute function app.party_guard();

create or replace function app.product_guard()
returns trigger
language plpgsql
as $$
begin
  if new.code is distinct from old.code then
    raise exception 'A product code cannot be changed (% stays %).', old.name, old.code
      using errcode = 'SA004';
  end if;

  if (new.opening_qty  is distinct from old.opening_qty
      or new.opening_rate is distinct from old.opening_rate
      or new.opening_date is distinct from old.opening_date)
     and public.product_opening_posted(old.id) then
    raise exception 'The opening stock of % has already been posted and cannot be changed here.',
      old.name using errcode = 'SA002';
  end if;

  return new;
end;
$$;

drop trigger if exists product_guard on public.product;
create trigger product_guard
  before update on public.product
  for each row execute function app.product_guard();

-- -----------------------------------------------------------------------------
-- What the Parties and Products screens read. One row per master, with the
-- names of what it points at and whether its opening figures are still open.
-- -----------------------------------------------------------------------------

create or replace view public.v_party_master as
select
  p.*,
  r.code  as route_code,
  r.name  as route_name,
  public.party_has_documents(p.id) as opening_locked
from public.party p
join public.route r on r.id = p.route_id;

create or replace view public.v_product_master as
select
  p.*,
  g.code  as group_code,
  g.name  as group_name,
  public.product_opening_posted(p.id) as opening_locked
from public.product p
join public.product_group g on g.id = p.group_id;

alter view public.v_party_master   set (security_invoker = true);
alter view public.v_product_master set (security_invoker = true);
grant select on public.v_party_master, public.v_product_master to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  020_revise_invoice.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 020_revise_invoice.sql
-- Correcting a bill on the day it was raised.
--
-- A posted invoice is immutable: stock movements, the customer's balance and
-- any print already given to the customer all hang off it. That rule is not
-- being relaxed. What this adds is a safe way to fix a bill typed wrongly
-- minutes ago, which in practice happens often and otherwise means an awkward
-- manual cancel-and-retype.
--
-- The correction is one transaction: the old bill is cancelled (goods back to
-- stock, order quantities back to pending, customer stops owing it) and a new
-- bill is raised from the corrected lines. Either both happen or neither does.
-- The old bill stays on record, marked cancelled, so the paper already handed
-- over can still be matched to something.
--
-- It is refused when:
--   * the bill was not raised today, or carries an earlier bill date;
--   * anything has already been cancelled on it;
--   * a payment or credit note has been applied to it — un-applying money is
--     a decision for a person, not a side effect of a typing correction.
--
-- The new bill gets the next number. The old number stays used and cancelled,
-- which is what an audit expects to see.
--
-- Run this file once in the Supabase SQL Editor. Safe to run more than once.
-- =============================================================================

create or replace function public.revise_sales_invoice(
  p_invoice_id           uuid,
  p_lines                jsonb,
  p_bill_discount_amount numeric default 0,
  p_bill_discount_pct    numeric default null,
  p_remarks              text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user    uuid := app.require_back_office();
  v_inv     public.sales_invoice%rowtype;
  v_settled numeric(14,2);
  v_new     jsonb;
begin
  select * into v_inv from public.sales_invoice where id = p_invoice_id for update;

  if not found then
    raise exception 'Unknown bill' using errcode = 'SA005';
  end if;

  if v_inv.status <> 'ACTIVE' then
    raise exception 'Bill % has already been cancelled in part or in full, so it cannot be corrected.',
      v_inv.doc_no using errcode = 'SA002';
  end if;

  if v_inv.invoice_date <> current_date or v_inv.created_at::date <> current_date then
    raise exception 'Bill % was not raised today. Raise a sales return or a cancellation instead.',
      v_inv.doc_no using errcode = 'SA002';
  end if;

  select coalesce(sum(amount), 0) into v_settled
    from public.credit_allocation where invoice_id = p_invoice_id;

  if v_settled > 0 then
    raise exception 'Bill % already has % applied to it. Undo the allocation first.',
      v_inv.doc_no, v_settled using errcode = 'SA002';
  end if;

  if jsonb_typeof(coalesce(p_lines, 'null'::jsonb)) <> 'array'
     or jsonb_array_length(p_lines) = 0 then
    raise exception 'A corrected bill still needs at least one line' using errcode = 'SA004';
  end if;

  -- Cancel first: this returns the goods to stock and the order lines to
  -- pending, which is exactly the state the new bill needs to be checked
  -- against. Both happen inside this one transaction.
  perform public.cancel_sales_invoice(
    p_invoice_id,
    'Corrected on the same day, replaced by a new bill');

  -- Cancelling a bill deliberately does NOT hand quantities back to its order:
  -- normally a cancellation ends the matter and the goods become free stock.
  -- A correction is the one case where the order should reopen, because the
  -- replacement bill is about to be raised against it. Reservations are
  -- released and retaken around the change so that `reserved` never counts the
  -- same goods twice.
  if v_inv.order_id is not null then
    perform app.release_order_reservation(v_inv.order_id);

    update public.sales_order_line sol
       set qty_invoiced_base = greatest(sol.qty_invoiced_base - x.qty, 0)
      from (select order_line_id, sum(qty_base) as qty
              from public.sales_invoice_line
             where invoice_id = p_invoice_id
               and order_line_id is not null
             group by order_line_id) x
     where sol.id = x.order_line_id;

    update public.sales_order so
       set status = case
                      when exists (select 1 from public.sales_order_line
                                    where order_id = v_inv.order_id
                                      and qty_invoiced_base > 0)
                      then 'PARTIALLY_INVOICED'::app.order_status
                      else 'SUBMITTED'::app.order_status
                    end,
           closed_at = null
     where so.id = v_inv.order_id;

    -- Raises SA001 if the goods have gone in the meantime, which aborts the
    -- whole correction and leaves the original bill standing.
    perform app.reserve_for_order(v_inv.order_id);
  end if;

  v_new := public.create_sales_invoice(
    v_inv.invoice_date,
    p_lines,
    v_inv.order_id,
    case when v_inv.order_id is null then v_inv.party_id end,
    p_bill_discount_amount,
    p_bill_discount_pct,
    coalesce(p_remarks, v_inv.remarks));

  return v_new || jsonb_build_object(
    'replaced_invoice_id', p_invoice_id,
    'replaced_doc_no',     v_inv.doc_no);
end;
$$;

revoke all on function
  public.revise_sales_invoice(uuid, jsonb, numeric, numeric, text)
from public, anon;

grant execute on function
  public.revise_sales_invoice(uuid, jsonb, numeric, numeric, text)
to authenticated;

comment on function public.revise_sales_invoice(uuid, jsonb, numeric, numeric, text) is
  'Same-day correction: cancels the bill and raises a replacement in one
   transaction. Refused once the bill is a day old, partly cancelled, or paid.';

-- >>>>>>>>>>>>>>>>>>>>  021_invoice_list.sql  <<<<<<<<<<<<<<<<<<<<

-- =============================================================================
-- 021_invoice_list.sql
-- Every bill in the list, and a link from a corrected bill to the one it
-- replaced.
--
-- Two problems this fixes.
--
-- First, the Bills screen was reading v_invoice_outstanding, which exists to
-- answer "who owes what" and therefore leaves cancelled bills out. Correct a
-- bill and its old number simply vanished from the list, which looks exactly
-- like data going missing. v_invoice_list below shows every bill, cancelled
-- ones included, and stays separate from the outstanding view so that ageing
-- and the receivables reports are untouched.
--
-- Second, nothing recorded that INV-000031 was raised because INV-000030 was
-- wrong. The two documents existed side by side with no connection. A single
-- column now records it, so both bills can say what happened.
--
-- Run this file once in the Supabase SQL Editor. Safe to run more than once.
-- =============================================================================

alter table public.sales_invoice
  add column if not exists replaces_invoice_id uuid
    references public.sales_invoice (id) on delete restrict;

comment on column public.sales_invoice.replaces_invoice_id is
  'Set when this bill was raised to correct another one the same day. The
   replaced bill is cancelled; this is how they stay connected.';

create index if not exists sales_invoice_replaces_idx
  on public.sales_invoice (replaces_invoice_id)
  where replaces_invoice_id is not null;

-- -----------------------------------------------------------------------------
-- The Bills screen: every bill, newest first, with what is still due on it.
-- Cancelled bills carry zero effective value, so they show as settled rather
-- than owing anything, and their status says what happened.
-- -----------------------------------------------------------------------------

create or replace view public.v_invoice_list as
select
  si.id            as invoice_id,
  si.doc_no,
  si.party_id,
  p.code           as party_code,
  p.name           as party_name,
  p.route_id,
  rt.name          as route_name,
  si.invoice_date,
  si.net_total,
  si.cancelled_value,
  si.effective_total,
  coalesce(ca.allocated, 0)                      as settled,
  si.effective_total - coalesce(ca.allocated, 0) as outstanding,
  current_date - si.invoice_date                 as days_outstanding,
  si.status,
  so.doc_no        as order_no,
  old.doc_no       as replaces_doc_no,
  si.replaces_invoice_id,
  new_one.doc_no   as replaced_by_doc_no,
  new_one.id       as replaced_by_invoice_id
from public.sales_invoice si
join public.party p   on p.id  = si.party_id
join public.route rt  on rt.id = p.route_id
left join public.sales_order so on so.id = si.order_id
left join public.sales_invoice old     on old.id = si.replaces_invoice_id
left join public.sales_invoice new_one on new_one.replaces_invoice_id = si.id
left join (
  select invoice_id, sum(amount) as allocated
    from public.credit_allocation
   group by invoice_id
) ca on ca.invoice_id = si.id;

alter view public.v_invoice_list set (security_invoker = true);
grant select on public.v_invoice_list to authenticated;

-- -----------------------------------------------------------------------------
-- Record the link when a bill is corrected.
--
-- Same function as 020 with one statement added at the end. Everything else,
-- including the rules about when a correction is allowed, is unchanged.
-- -----------------------------------------------------------------------------

create or replace function public.revise_sales_invoice(
  p_invoice_id           uuid,
  p_lines                jsonb,
  p_bill_discount_amount numeric default 0,
  p_bill_discount_pct    numeric default null,
  p_remarks              text    default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_catalog
as $$
declare
  v_user    uuid := app.require_back_office();
  v_inv     public.sales_invoice%rowtype;
  v_settled numeric(14,2);
  v_new     jsonb;
begin
  select * into v_inv from public.sales_invoice where id = p_invoice_id for update;

  if not found then
    raise exception 'Unknown bill' using errcode = 'SA005';
  end if;

  if v_inv.status <> 'ACTIVE' then
    raise exception 'Bill % has already been cancelled in part or in full, so it cannot be corrected.',
      v_inv.doc_no using errcode = 'SA002';
  end if;

  if v_inv.invoice_date <> current_date or v_inv.created_at::date <> current_date then
    raise exception 'Bill % was not raised today. Raise a sales return or a cancellation instead.',
      v_inv.doc_no using errcode = 'SA002';
  end if;

  select coalesce(sum(amount), 0) into v_settled
    from public.credit_allocation where invoice_id = p_invoice_id;

  if v_settled > 0 then
    raise exception 'Bill % already has % applied to it. Undo the allocation first.',
      v_inv.doc_no, v_settled using errcode = 'SA002';
  end if;

  if jsonb_typeof(coalesce(p_lines, 'null'::jsonb)) <> 'array'
     or jsonb_array_length(p_lines) = 0 then
    raise exception 'A corrected bill still needs at least one line' using errcode = 'SA004';
  end if;

  perform public.cancel_sales_invoice(
    p_invoice_id,
    'Corrected on the same day, replaced by a new bill');

  -- Cancelling a bill deliberately does NOT hand quantities back to its order:
  -- normally a cancellation ends the matter and the goods become free stock.
  -- A correction is the one case where the order should reopen, because the
  -- replacement bill is about to be raised against it. Reservations are
  -- released and retaken around the change so that `reserved` never counts the
  -- same goods twice.
  if v_inv.order_id is not null then
    perform app.release_order_reservation(v_inv.order_id);

    update public.sales_order_line sol
       set qty_invoiced_base = greatest(sol.qty_invoiced_base - x.qty, 0)
      from (select order_line_id, sum(qty_base) as qty
              from public.sales_invoice_line
             where invoice_id = p_invoice_id
               and order_line_id is not null
             group by order_line_id) x
     where sol.id = x.order_line_id;

    update public.sales_order so
       set status = case
                      when exists (select 1 from public.sales_order_line
                                    where order_id = v_inv.order_id
                                      and qty_invoiced_base > 0)
                      then 'PARTIALLY_INVOICED'::app.order_status
                      else 'SUBMITTED'::app.order_status
                    end,
           closed_at = null
     where so.id = v_inv.order_id;

    perform app.reserve_for_order(v_inv.order_id);
  end if;

  v_new := public.create_sales_invoice(
    v_inv.invoice_date,
    p_lines,
    v_inv.order_id,
    case when v_inv.order_id is null then v_inv.party_id end,
    p_bill_discount_amount,
    p_bill_discount_pct,
    coalesce(p_remarks, v_inv.remarks));

  -- The one new line: remember which bill this one replaced.
  update public.sales_invoice
     set replaces_invoice_id = p_invoice_id
   where id = (v_new ->> 'invoice_id')::uuid;

  return v_new || jsonb_build_object(
    'replaced_invoice_id', p_invoice_id,
    'replaced_doc_no',     v_inv.doc_no);
end;
$$;

grant execute on function
  public.revise_sales_invoice(uuid, jsonb, numeric, numeric, text)
to authenticated;
